function HousingMgr:GetEstateID()
    local MapResID = _G.PWorldMgr:GetCurrMapResID()
    if self.EstateInfoCfg == nil then
        self.EstateInfoCfg = {}
        local Cfgs = EstateInfoCfg:FindAllCfg()

        for k,v in pairs(Cfgs) do
            self.EstateInfoCfg[v.MapID] = v.ID
        end
    end

    for k,v in pairs(self.EstateInfoCfg) do
        if k == MapResID then
            return v
        end
    end

    return 0
end

--查找房区地块对应的房子大小
function HousingMgr:FindLandBlockSize(EstateID,BlockID)
    --建立映射关系
    if self.LandCfg[EstateID] ~= nil then
        for k,v in ipairs(self.LandCfg[EstateID]) do
            if k == BlockID then
                return v
            end
        end
    end

    return nil
end

function HousingMgr:CreateFurnitureObjectIDToIndexMap()
    self.FurnitureObjectIDToIndexMap = {}
    -- 要等lua5.5才能预分配空间，现在还没法优化
    for i=1,400 do
        table.insert(self.FurnitureObjectIDToIndexMap,0)
    end
end

function HousingMgr:GetFurnitureObjectIndex(GID)
    for k,v in pairs(self.FurnitureObjectIDToIndexMap) do
        if v == GID then
            return k
        end
    end

    return 0
end

function HousingMgr:CreateYardObjectIDToIndexMap(EstateID,AreaSubID)
    if self.LandCfg == nil then
        self.LandCfg = {}
        local Cfgs = LandCondCfg:FindAllCfg()

        for k,v in pairs(Cfgs) do
            if self.LandCfg[v.EstateID] == nil then
                self.LandCfg[v.EstateID] = {}
            end

            table.insert(self.LandCfg[v.EstateID],v.BlockID,v.Size)
        end
    end

    self.YardObjectIDToIndexMap = {}

    local AreaBlockBegin = AreaSubID == 1 and 1 or 31
    local AreaBlockEnd = AreaSubID == 1 and 30 or 60

    if self.LandCfg[EstateID] ~= nil then
        for k,v in pairs(self.LandCfg[EstateID]) do
            if k >= AreaBlockBegin and k <= AreaBlockEnd then
                if v == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_S then
                    for i=1,20 do
                        table.insert(self.YardObjectIDToIndexMap,0)
                    end
                elseif v == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_M then
                    for i=1,30 do
                        table.insert(self.YardObjectIDToIndexMap,0)
                    end
                elseif v == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_L then
                    for i=1,40 do
                        table.insert(self.YardObjectIDToIndexMap,0)
                    end
                end
            end
        end
    end
end

function HousingMgr:CheckAndSetPickObjectRotate(Rotate)
    local Count = #self.PickEndObjectInfos
    if (self.PickIndex == nil) or (Count == 0) then
        _G.FLOG_ERROR("HousingMgr:CheckAndSetPickObjectRotate error", self.PickIndex, Count)
        return
    end

    local GID = 0
    if self:IsInDoor() then
        GID = self.FurnitureObjectIDToIndexMap[self.PickIndex + 1]
    else
        GID = self.YardObjectIDToIndexMap[self.PickIndex + 1]
    end

    for k, v in pairs(self.PickEndObjectInfos) do
        if v.GID == GID then
            v.Yaw = Rotate
        end
    end

    local HousingMgrInstance = UHousingMgr:Get()
    if HousingMgrInstance ~= nil then
        HousingMgrInstance:CheckAndSetPickObjectRotate(self.PickIndex, Rotate)
    end
end

function HousingMgr:CheckAndSetPickObjectZ(Z)
    local Count = #self.PickEndObjectInfos
    if (self.PickIndex == nil) or (Count == 0) then
        _G.FLOG_ERROR("HousingMgr:CheckAndSetPickObjectZ error", self.PickIndex, Count)
        return
    end

    local GID = 0
    if self:IsInDoor() then
        GID = self.FurnitureObjectIDToIndexMap[self.PickIndex + 1]
    else
        GID = self.YardObjectIDToIndexMap[self.PickIndex + 1]
    end

    for _, v in ipairs(self.PickEndObjectInfos) do
        if v.GID == GID then
            v.Z = Z
            break
        end
    end

    local HousingMgrInstance = UHousingMgr:Get()
    if HousingMgrInstance ~= nil then
        HousingMgrInstance:CheckAndSetPickObjectZ(self.PickIndex, Z)
    end
end

function HousingMgr:GetPickObjectHeight()
    local Count = #self.PickEndObjectInfos
    if (self.PickIndex == nil) or (Count == 0) then
        _G.FLOG_ERROR("HousingMgr:GetPickObjectHeight error", self.PickIndex, Count)
        return 0, 0
    end

    local GID = 0
    if self:IsInDoor() then
        GID = self.FurnitureObjectIDToIndexMap[self.PickIndex + 1]
    else
        GID = self.YardObjectIDToIndexMap[self.PickIndex + 1]
    end

    local CurrZ, GroundZ = 0, 0
    for _, v in ipairs(self.PickEndObjectInfos) do
        if v.GID == GID then
            CurrZ, GroundZ = v.Z, v.Z
            break
        end
    end

    local HousingMgrInstance = UHousingMgr:Get()
    if HousingMgrInstance ~= nil then
        GroundZ = HousingMgrInstance:GetPickObjectGroundZ(self.PickIndex)
    end

    local Height = CurrZ - GroundZ
    if Height < 0 then
        _G.FLOG_INFO("HousingMgr:GetPickObjectHeight Height < 0, PickIndex=%d, CurrZ=%.1f, GroundZ=%.1f",
            self.PickIndex, CurrZ, GroundZ)
        Height = 0
    end

    return GroundZ, Height
end

function HousingMgr:RefreshPickObjectsInfo()
    if (#self.MultiFixIndexList == 0) then return end
    local HousingMgrInstance = UHousingMgr:Get()
    if (HousingMgrInstance == nil) then return end

    local FixIndexs = _G.UE.TArray(_G.UE.uint16)
    for _, FixIndex in ipairs(self.MultiFixIndexList) do
        FixIndexs:Add(FixIndex)
    end
    HousingMgrInstance:RefreshPickObjectsInfo(FixIndexs)
    self.MultiFixIndexList = {}
end

