--按下
function HousingMgr:OnPickStart(FixIndex)
    if self.HouseDecorateDataManager[self.HouseID] == nil or self.HouseDecorateDataManager[self.HouseID][self.Region] == nil then
        return
    end
    local Furniture = self.HouseDecorateDataManager[self.HouseID][self.Region].Furniture
    if Furniture == nil then
        return
    end

    if self.Region == ProtoRes.HouseRegionType.HouseRegionType_Yard then
        local GID = self.YardObjectIDToIndexMap[FixIndex + 1]
        for _, Entity in ipairs(Furniture.Entities) do
            if Entity.GID == GID then
                self.PickIndex = FixIndex
                local Cfg = HousingYardCfg:FindCfgByKey(Entity.Key)

                if Cfg ~= nil then
                    _G.EventMgr:SendEvent(_G.EventID.EnterHouseFurniturePreview, {
                        Item = { GID = GID, ResID = Cfg.ItemID },
                        Rotate = Entity.Pos.Yaw,
                        Source = HouseCommon.FurnitureSource.BagDepot
                    })
                    return
                end
            end
        end
    else
        local GID = self.FurnitureObjectIDToIndexMap[FixIndex + 1]
        for _, Entity in ipairs(Furniture.Entities) do
            if Entity.GID == GID then
                self.PickIndex = FixIndex
                local Cfg = HousingFurnitureCfg:FindCfgByKey(Entity.Key)

                if Cfg ~= nil then
                    _G.EventMgr:SendEvent(_G.EventID.EnterHouseFurniturePreview, {
                        Item = { GID = GID, ResID = Cfg.ItemID },
                        Rotate = Entity.Pos.Yaw,
                        Source = HouseCommon.FurnitureSource.BagDepot
                    })
                    return
                end
            end
        end
    end
end

function HousingMgr:InsertPickEndObjectInfo(FixIndex, X, Y, Z, Yaw)
    local info = { X = X, Y = Y, Z = Z, Yaw = Yaw }
    if self:IsInDoor() then
        info.GID = self.FurnitureObjectIDToIndexMap[FixIndex + 1]
    else
        info.GID = self.YardObjectIDToIndexMap[FixIndex + 1]
    end
    table.insert(self.PickEndObjectInfos, info)
end

--点击选中物件(抬起)
function HousingMgr:OnPickEnd(FixIndex, X, Y, Z, Yaw)
    if FixIndex >= 0 then
        self.PickEndObjectInfos = {}
        self:InsertPickEndObjectInfo(FixIndex, X, Y, Z, Yaw)
    end
    _G.EventMgr:SendEvent(_G.EventID.PickEndFurniture)
end

function HousingMgr:OnPickEndMulti(FixIndexs, PosXs, PosYs, PosZs, Yaws)
    self.PickEndObjectInfos = {}
    local bCacheFixIndex = (#self.MultiFixIndexList == 0)

    local Count = FixIndexs:Length()
    for i = 1, Count do
        local FixIndex = FixIndexs:Get(i)
        if FixIndex and (FixIndex >= 0) then
            self:InsertPickEndObjectInfo(FixIndex, PosXs[i], PosYs[i], PosZs[i], Yaws[i])
            if bCacheFixIndex then
                table.insert(self.MultiFixIndexList, FixIndex)
            end
        end
    end
    _G.EventMgr:SendEvent(_G.EventID.PickEndFurniture)
end

function HousingMgr:OnRefreshPickObjectsInfo(FixIndexs, PosXs, PosYs, PosZs, Yaws)
    self.PickEndObjectInfos = {}
    local Count = FixIndexs:Length()
    for i = 1, Count do
        local FixIndex = FixIndexs:Get(i) or -1
        if FixIndex >= 0 then
            self:InsertPickEndObjectInfo(FixIndex, PosXs[i], PosYs[i], PosZs[i], Yaws[i])
        end
    end
end

--物件放置结束发包到后台
function HousingMgr:OnAppendEnd(X,Y,Z,Yaw)
    local TabIndex = HouseMainPanelVM:GetTabSelectIndex()
    local BagType = ProtoCS.HouseUseBagType.HouseUseBagType_RoleBag

    if TabIndex == HouseCommon.SelectHouseLeftBarType.StoreHouse then
        BagType = ProtoCS.HouseUseBagType.HouseUseBagType_HouseDepot
    end
    
    local ObjResID = self.TemporaryHosingObjectResID
    local ObjGID = self.TemporaryHosingObjectGID
    local function Callback()
        local Cfg = HouseUtil.GetHousePartsCfg(ObjResID)

        if Cfg ~= nil then
            self:SendPutFurnitureReq(BagType, 
                    { GID = ObjGID, ResID = ObjResID },
                    { X = math.ceil(X), Y = math.ceil(Y), Z = math.ceil(Z) }, math.ceil(Yaw), Cfg.Key)
        end
    end

    local function CallBackCancel()
        local HousingMgrInstance = UHousingMgr:Get()
        if HousingMgrInstance ~= nil then
            HousingMgrInstance:ClearTemporaryHosingObject()
        end
    end

    local RealItem = _G.BagMgr:FindItem(self.TemporaryHosingObjectGID)

    if RealItem ~= nil and not RealItem.IsBind then
        --弹二次确认
        local EnlargeRichText = RichTextUtil.GetText(string.format("%s", _G.LSTR(1640071)), YellowHex)
        local Params = {FontSize = 22,TextAlignment = CommonBoxDefine.BtnType.Left}
        local DecorateText = string.format(_G.LSTR(1640070), EnlargeRichText)
        MsgBoxUtil.ShowMsgBoxMTwoOp(self,_G.LSTR(1640044),DecorateText,Callback,CallBackCancel,nil,nil,Params)
    else
        Callback()
    end
end

function HousingMgr:CanPick(FixIndex)
    if self.PickIndex ~= nil then
        if self.PickIndex == FixIndex then
            return true
        else
            self:OnPickOther()
            return false
        end
    end

    return true
end

function HousingMgr:CheckCreateFurnitureEObj(Key, FixIndex)
    if Key > 0 then
        if self:CheckInDoor() then
            local cfg = HousingFurnitureCfg:FindCfgByKey(Key)
            if cfg ~= nil then
                if cfg.EObjID > 0 then
                    if cfg.Function > 0 then
                        if cfg.Function == ProtoRes.HouseFurnitureFunction.HouseFurnitureFunction_Food then --食物
                            local FurnitureID = self.FurnitureObjectIDToIndexMap[FixIndex + 1]
                            if FurnitureID > 0 then
                                local Furniture = self:GetFurnitureInfo(FurnitureID)
                                if Furniture ~= nil then
                                    --现在一次也没有吃则是空的，后面一次没吃有数据的话也可以按后面的处理
                                    if Furniture.Attr.Data == nil then
                                        return true
                                    elseif  Furniture.Attr.Food.EatedTimes >= cfg.FuncParam[1] then
                                        return false
                                    else
                                        return true
                                    end
                                end
                            else
                                return false
                            end
                        else
                            return true
                        end
                    end
                end
            end
        else
            local cfg = HousingYardCfg:FindCfgByKey(Key)
            if cfg ~= nil then
                if cfg.EObjID > 0 then
                    return true
                end
            end
        end
    end

    return false
end

