function HousingMgr:CheckInDoor()
    local InDoor = false
    local CurWorldSubType = _G.PWorldMgr:GetCurrPWorldSubType()
    if CurWorldSubType == ProtoRes.pworld_sub_type.PWORLD_SUB_TYPE_HOUSE_PUBLIC then
        InDoor = false
    elseif CurWorldSubType == ProtoRes.pworld_sub_type.PWORLD_SUB_TYPE_HOUSE_ROOM then
        InDoor = true
    end

    return InDoor
end


--通过家具GID找到家具信息
function HousingMgr:GetFurnitureInfo(FurnitureID)
    if self:CheckInDoor() then
        if self.HouseDecorateDataManager[self.IndoorHouseID][ProtoRes.HouseRegionType.HouseRegionType_Room] ~= nil then
            if self.HouseDecorateDataManager[self.IndoorHouseID][ProtoRes.HouseRegionType.HouseRegionType_Room].Furniture ~= nil then
                for _,Entity in pairs(self.HouseDecorateDataManager[self.IndoorHouseID][ProtoRes.HouseRegionType.HouseRegionType_Room].Furniture.Entities) do
                    if Entity.GID == FurnitureID then
                        return Entity
                    end
                end
            end
        end
    else
        for k,v in pairs(self.HouseDecorateDataManager) do
            if self.HouseDecorateDataManager[k][ProtoRes.HouseRegionType.HouseRegionType_Yard] ~= nil then
                if self.HouseDecorateDataManager[k][ProtoRes.HouseRegionType.HouseRegionType_Yard].Furniture ~= nil then
                    for _,Entity in pairs(self.HouseDecorateDataManager[k][ProtoRes.HouseRegionType.HouseRegionType_Yard].Furniture.Entities) do
                        if Entity.GID == FurnitureID then
                            return Entity
                        end
                    end
                end
            end
        end
    end

    return nil
end

