function HousingMgr:FindSubFixIndex(AreaSubID,EstateID,BlockID,GID)
    local fixIndex = 1
    local AreaBlockBegin = AreaSubID == 1 and 1 or 31
    for i=AreaBlockBegin,BlockID-1 do
        local Size = self:FindLandBlockSize(EstateID,i)
        if Size == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_S then
            fixIndex = fixIndex + 20
        elseif Size == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_M then
            fixIndex = fixIndex + 30
        elseif Size == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_L then
            fixIndex = fixIndex + 40
        end
    end

    for k=fixIndex,#self.YardObjectIDToIndexMap do
        if self.YardObjectIDToIndexMap[k] == GID then
            return k - fixIndex
        end
    end

    return 0
end

function HousingMgr:FindFixIndex(AreaSubID,EstateID,BlockID,GID)
    --创建服务器ID与客户端INDEX之间的映射
    local fixIndex = 1
    local AreaBlockBegin = AreaSubID == 1 and 1 or 31
    for i=AreaBlockBegin,BlockID-1 do
        local Size = self:FindLandBlockSize(EstateID,i)
        if Size == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_S then
            fixIndex = fixIndex + 20
        elseif Size == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_M then
            fixIndex = fixIndex + 30
        elseif Size == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_L then
            fixIndex = fixIndex + 40
        end
    end

    for k=fixIndex,#self.YardObjectIDToIndexMap do
        if self.YardObjectIDToIndexMap[k] == GID then
            return k
        end
    end

    return 0
end

function HousingMgr:EnterHouseBlock(BlockID)
    for k,v in pairs(self.HouseDecorateDataManager) do
        --走出了可操作庭院
        if self.HouseID > 0 and k == self.HouseID and BlockID == 0 and self.CurrentHousingBlockId > 0 then
            if self.HouseDecorateDataManager[k][ProtoRes.HouseRegionType.HouseRegionType_Yard] ~= nil then
                if self.HouseDecorateDataManager[k][ProtoRes.HouseRegionType.HouseRegionType_Yard].Addr.Number == self.CurrentHousingBlockId then
                    self.HouseID = 0
                    self.CurrentHousingBlockId = BlockID
                    _G.EventMgr:SendEvent(EventID.ShowDecorateView,{Enable = false})
                    _G.EventMgr:SendEvent(EventID.ExitHouseRange)
                    return
                end
            end
        end

        --进入自己可编辑的house庭院
        if k == self.OwnHouseID or k == self.SharedHouseID or k == self.ArmyHouseID then
            if self.HouseDecorateDataManager[k][ProtoRes.HouseRegionType.HouseRegionType_Yard] ~= nil then
                -- 住宅区，小区，门牌依次判断
                if self.HouseDecorateDataManager[k][ProtoRes.HouseRegionType.HouseRegionType_Yard].Addr.EstateID == self.CurrentHousingEstateID then
                    if self.HouseDecorateDataManager[k][ProtoRes.HouseRegionType.HouseRegionType_Yard].Addr.Area == self.CurrentHousingAreaId then
                        if self.HouseDecorateDataManager[k][ProtoRes.HouseRegionType.HouseRegionType_Yard].Addr.Number == BlockID then
                            self.CurrentHousingBlockId = BlockID
                            self.HouseID = k
                            _G.EventMgr:SendEvent(EventID.ShowDecorateView,{Enable = true})
                            MsgTipsUtil.ShowTips(_G.LSTR(1640144))
                            --拉取仓库信息
                            self:SendHouseDepotReq()
                        end
                    end
                    
                end
            end
        end
    end

    self.CurrentHousingBlockId = BlockID
end

