---@param HouseID number
---@param Region HouseRegionType
---@param DecorateInfo ClientDecorateInfo
function HousingMgr:UpdateHouseDecorateData(HouseID, Region, DecorateInfo)
    if self.HouseDecorateDataManager[HouseID] == nil then
        --之前没有的话要加入
        self.HouseDecorateDataManager[HouseID] = {
            [ProtoRes.HouseRegionType.HouseRegionType_Room] = {},
            [ProtoRes.HouseRegionType.HouseRegionType_Yard] = {},
        }
    end
    --刷新数据
    self.HouseDecorateDataManager[HouseID][Region] = DecorateInfo
    self.BlockToHouseIDMap[DecorateInfo.Addr.Number] = HouseID

    --对位置排序
    for _, Floor in pairs(DecorateInfo.DoUp.Floors) do
        table.sort(Floor.Entities, function(A, B)
            return A.Pos < B.Pos
        end)
    end

    --更改服务器楼层ID与SE楼层ID匹配
    if DecorateInfo.DoUp ~= nil and DecorateInfo.DoUp.Floors ~= nil then
        for _, Floor in pairs(DecorateInfo.DoUp.Floors) do
            Floor.Floor = HouseUtil.ConvertServerFloorToClientFloor(Floor.Floor)
            for _, Entity in pairs(Floor.Entities) do
                Entity.Floor = HouseUtil.ConvertServerFloorToClientFloor(Entity.Floor)
            end
        end
    end
    if DecorateInfo.DoUp ~= nil and DecorateInfo.DoUp.Global ~= nil then
        for _, Entity in pairs(DecorateInfo.DoUp.Global.Entities) do
            Entity.Floor = HouseUtil.ConvertServerFloorToClientFloor(Entity.Floor)
        end
    end

    --对楼层排序
    table.sort(DecorateInfo.DoUp.Floors, function(A, B)
        return A.Floor < B.Floor
    end)
end

