    end

    return nil
end

function HousingMgr:GetDepotItems(ItemDetailTypeList)
    local CurrentDepot = self:GetCurrentDepot()
    local TableItemDetailList = {}
    for _, v in ipairs(ItemDetailTypeList) do
        table.insert(TableItemDetailList, HouseUtil.ConvertHouseItemTabCategoryToItemTypeDetail(v))
    end

    local ItemList = {}
    for _, Item in ipairs(CurrentDepot.ItemList) do
        local Cfg = ItemCfg:FindCfgByKey(Item.ResID)
        if Cfg and Cfg.Classify == ITEM_CLASSIFY_TYPE.ITEM_CLASSIFY_HOUSE then
            for _, TargetType in ipairs(TableItemDetailList) do
                if Cfg.ItemType == TargetType then
                    table.insert(ItemList, Item)
                    break
                end
            end
        end
    end
    return ItemList
end

function HousingMgr:SetDepotCapacity()
    --之前获取仓库总大小时可能没有收到
    local RegionCfg = self:GetHouseRegionCfg()
    if not RegionCfg then return end

    local CurrentDepot = self:GetCurrentDepot()
    if CurrentDepot.Capacity == 0 then
