--放置室内家具
function HousingMgr:PlaceIndoorFurnitureList(FurnitureList)
    local FurnitureData = ZoneProtoDownGAME_FurnitureList()
    FurnitureData.LandID = 0
    FurnitureData.LandType = 0

    for k,v in pairs(FurnitureList.Entities) do
        local Furniture = ZoneProtoDownGAME_Furniture()
        Furniture.FixIndex = self:GetFurnitureObjectIndex(v.GID) - 1
        Furniture.Furniture = ZoneProtoDownFurniture()
        Furniture.Furniture.HousingBaseIDLow = v.Key & 0xFFFF --取低16位的值
        Furniture.Furniture.TimelineState = 0
        Furniture.Furniture.ColorID = v.Attr.ColorID
        Furniture.Furniture.Dir = v.Pos.Yaw
        Furniture.Furniture.Pos = _G.UE.FVector(v.Pos.X,v.Pos.Y,v.Pos.Z)

        if v.Attr.Data ~= nil then
            -- 说明是食物相关的家具
            if v.Attr.Food ~= nil then
                Furniture.Furniture.TimelineState = _G.FurnitureInteractionMgr:GetFurnitureTimelineState(v)
            elseif v.Attr.Status ~= nil then
                Furniture.Furniture.TimelineState =  v.Attr.Status.CurStatus
            end
        end
        
        FurnitureData.Furnitures:Add(Furniture)
    end

    local HousingMgrInstance = UHousingMgr:Get()
    if HousingMgrInstance ~= nil then
        HousingMgrInstance:OnReceiveFurnitureList(FurnitureData)
    end
end

--放置庭具
function HousingMgr:PlaceYardList(Furnitures)
    local FurnitureData = ZoneProtoDownGAME_FurnitureList()
    FurnitureData.LandID = 0
    FurnitureData.LandType = 0

    for k,v in ipairs(Furnitures) do
        if #v.Furniture.Entities > 0 then
            for x,y in ipairs(v.Furniture.Entities) do
                local Furniture = ZoneProtoDownGAME_Furniture()
                Furniture.FixIndex = self:FindFixIndex(self.CurrentHousingAreaSubId,self:GetEstateID(),v.Block,y.GID) - 1
                Furniture.Furniture = ZoneProtoDownFurniture()
                Furniture.Furniture.HousingBaseIDLow = y.Key & 0xFFFF --取低16位的值
                Furniture.Furniture.TimelineState = 0
                Furniture.Furniture.ColorID = y.Attr.ColorID
                Furniture.Furniture.Dir = y.Pos.Yaw
                Furniture.Furniture.Pos = _G.UE.FVector(y.Pos.X,y.Pos.Y,y.Pos.Z)
                FurnitureData.Furnitures:Add(Furniture)
            end
        end
    end

    local HousingMgrInstance = UHousingMgr:Get()
    if HousingMgrInstance ~= nil then
        HousingMgrInstance:OnReceiveFurnitureList(FurnitureData)
    end
end

--清空房屋
function HousingMgr:HideHouse(HouseID)
    local DecorateData = self.HouseDecorateDataManager[HouseID][ProtoRes.HouseRegionType.HouseRegionType_Yard]
    if DecorateData.Addr == nil then -- 只输出日志，上线前暂不处理流程，方便发现问题
        _G.FLOG_ERROR("HousingMgr:HideHouse Addr is nil, DecorateData=%s", _G.TableToString(DecorateData))
    end
    local BlockID = DecorateData.Addr.Number

    if self.Region == ProtoRes.HouseRegionType.HouseRegionType_Yard then
        --if self.SharedHouseID == HouseID then  --移动到方法外处理
        --    self:SetSharedHouseID(0)
        --end

        -- 如果玩家在当前房子范围内
        if self.HouseID == HouseID then
            --self.CurrentHousingBlockId = 0
            _G.EventMgr:SendEvent(EventID.ShowDecorateView, { Enable = false })
            _G.EventMgr:SendEvent(EventID.ExitHouseRange)
        end

        local ExteriorData = ZoneProtoDownGAME_House()
        ExteriorData.Block = BlockID
        ExteriorData.Size = HousingMgr:GetHouseSize(HouseID)

        for _ = 1, 8 do
            ExteriorData.ExteriorIds:Add(0)
            ExteriorData.Colors:Add(0)
        end

        local HousingMgrInstance = UHousingMgr:Get()
        if HousingMgrInstance ~= nil then
            _G.FLOG_INFO("HousingMgr:OnUpdateHouse Hide HouseID = : %s", tostring(HouseID))
            HousingMgrInstance:OnUpdateHouse(ExteriorData)
        end

    elseif self.IndoorHouseID == HouseID then
        -- 房子已拆除，需要传送出去
    end

    self.BlockToHouseIDMap[BlockID] = nil
    self.HouseDecorateDataManager[HouseID] = nil
end

-- 刷新房子整体装修
function HousingMgr:RefreshHouseDecorate(Params)
    --如果是庭院则需要根据blockid来刷新对应房子的外装
    if Params.Region == ProtoRes.HouseRegionType.HouseRegionType_Yard then
        local ExteriorData = ZoneProtoDownGAME_House()
        ExteriorData.Block = 0
        ExteriorData.Size = HousingMgr:GetHouseSize(Params.HouseID)
        local ExteriorIds = {}

        for i=1,8 do
            table.insert(ExteriorIds,0)
            ExteriorData.Colors:Add(0)
        end

        if self.HouseDecorateDataManager[Params.HouseID] ~= nil then
            local DecorateData = self.HouseDecorateDataManager[Params.HouseID][ProtoRes.HouseRegionType.HouseRegionType_Yard]
            for k,v in pairs(DecorateData.DoUp.Floors) do
                for _,Entity in pairs(v.Entities) do
                    if Entity.GID > 0 then
                        local Pos = HouseUtil.GetOutDoorPosToIndex(Entity.Pos)
                        ExteriorIds[Pos] = Entity.Key
                    end
                end
            end

            for k,v in ipairs(ExteriorIds) do
                ExteriorData.ExteriorIds:Add(v)
            end

            ExteriorData.Block = DecorateData.Addr.Number

            local HousingMgrInstance = UHousingMgr:Get()
            if HousingMgrInstance ~= nil then
                HousingMgrInstance:OnUpdateHouse(ExteriorData)
            end
        end
    else
        local InteriorData = ZoneProtoDownGAME_Interior()
        InteriorData.WindowColor = 0
        InteriorData.DoorColor = 0
        InteriorData.WindowExteriorId = 0
        InteriorData.DoorExteriorId = 0
        InteriorData.LightLevel = self.LightPower

        for _ = 1, 10 do -- enum HouseInteriorParts, skysong之前没移植这个枚举到lua，先手动填
            InteriorData.InteriorIds:Add(0)
        end

        if self.HouseDecorateDataManager[Params.HouseID] ~= nil then
            for k, v in pairs(self.HouseDecorateDataManager[Params.HouseID][ProtoRes.HouseRegionType.HouseRegionType_Room].DoUp.Floors) do
                if v.Floor == HouseCommon.FloorCategory.FLOOR_CATEGORY_1F then
                    for Index, Entity in pairs(v.Entities) do
                        if Entity.GID > 0 then
                            InteriorData.InteriorIds[Index] = Entity.Key
                        end
                    end
                elseif v.Floor == HouseCommon.FloorCategory.FLOOR_CATEGORY_2F then
                    for Index, Entity in pairs(v.Entities) do
                        if Entity.GID > 0 then
                            InteriorData.InteriorIds[3 + Index] = Entity.Key
                        end
                    end
                else
                    for Index, Entity in pairs(v.Entities) do
                        if Entity.GID > 0 then
                            InteriorData.InteriorIds[6 + Index] = Entity.Key
                        end
                    end
                end
            end
        end

        local CenterLightEntity = self:GetHouseCenterLightEntity(Params.HouseID)
        if CenterLightEntity ~= nil then
            InteriorData.InteriorIds[10] = CenterLightEntity.Key
        end

        if self.HouseDecorateDataManager[Params.HouseID][ProtoRes.HouseRegionType.HouseRegionType_Room].ExtraDoUp ~= nil then
            for k,v in pairs(self.HouseDecorateDataManager[Params.HouseID][ProtoRes.HouseRegionType.HouseRegionType_Room].ExtraDoUp) do
                if v.Pos == ProtoRes.HouseDoUpPos.HouseDoUpPos_YardWindow then
                    InteriorData.WindowExteriorId = v.Key

                    if v.Attr ~= nil then
                        InteriorData.WindowColor = v.Attr.ColorID
                    else
                        InteriorData.WindowColor = 0
                    end

                elseif v.Pos == ProtoRes.HouseDoUpPos.HouseDoUpPos_YardDoor then
                    InteriorData.DoorExteriorId = v.Key

                    if v.Attr ~= nil then
                        InteriorData.DoorColor = v.Attr.ColorID
                    else
                        InteriorData.DoorColor = 0
                    end
                end
            end
        end

        local HousingMgrInstance = UHousingMgr:Get()
        if HousingMgrInstance ~= nil then
            HousingMgrInstance:OnReceiveInterior(InteriorData)
        end
    end

    FLOG_INFO("RefreshHouseDecorate HouseID is %d",Params.HouseID)
end

