-- 监听游戏登录事件
function HousingMgr:OnGameEventLoginRes(Params)
    local bReconnect = Params and Params.bReconnect

    -- HouseInfoMgr 会请求，这里先注释
    --self:SendPullRoleInfoReq()

    --断线重连的处理
    if bReconnect then
        --拉取房子信息
        local CurWorldSubType = _G.PWorldMgr:GetCurrPWorldSubType()
        --只在HOUSE地图才需要重拉HOUSE信息
        if CurWorldSubType == ProtoRes.pworld_sub_type.PWORLD_SUB_TYPE_HOUSE_PUBLIC or CurWorldSubType == ProtoRes.pworld_sub_type.PWORLD_SUB_TYPE_HOUSE_ROOM then
            if self.InDoor then
                --这里IndoorHouseID肯定不为0，不然就是异常了,同步装修信息
                if self.IndoorHouseID > 0 then
                    self.FurnitureEobjGIDMap = {}
                    self:SendPullDecorateReq({self.IndoorHouseID}, self.Region, true)
                else
                    FLOG_WARNING("IndoorHouseID Is Zero")
                end
            else
                self.FurnitureEobjGIDMap = {}
                --公共地图则需要拉取所有的房子外装信息
                self:SendPullEstateHouseReq()
            end

            --只有当当前地图可操作才拉取仓库信息
            if self.HouseID > 0 then
                --拉取仓库信息
                self:SendHouseDepotReq()
            end
        end
    end
end

