--进入地图
function HousingMgr:OnPWorldMapEnter()
    local HousingMgrInstance = UHousingMgr:Get()
    if HousingMgrInstance ~= nil then
        if _G.PWorldMgr:CurrIsInHousing() then
            local MapOwnerID = _G.PWorldMgr:GetOwnerID()
            if _G.PWorldMgr:CurrIsInHousingPublic() then
                HousingMgrInstance:OnTerritoryIn(1)
                self:SetHouseRegion(ProtoRes.HouseRegionType.HouseRegionType_Yard)

                local Low16 = MapOwnerID % 0x10000
                local AreaID = Low16 >= 0 and Low16 or Low16 + 0x10000
                local EstateID = HouseUtil.GetEstateID()
                local AreaSubID = HouseUtil.GetCurrentAreaSubID()
                
                --拉取当前地图所有HOUSE的外装信息
                self:SetHousingEstateID(EstateID)
                self:SetHousingArea(AreaID)
                self:SetHousingAreaSubID(AreaSubID)
                --拉取当前公共地图所有房屋信息
                self:SendPullEstateHouseReq()
                -- 在EnterPworld的時候触发一下EnterHouseBlock,因为之前触发的时候，没有小区ID
                self:EnterHouseBlock(self.CurrentHousingBlockId)
            else
                HousingMgrInstance:OnTerritoryIn(2)
                self:SetHouseRegion(ProtoRes.HouseRegionType.HouseRegionType_Room)
                --拉取当前地图内装信息
                --获取当前地图的houseID这里是测试代码正式不能用self.houseid,self.houseid只用于自己能编辑的房子

                self:SetIndoorHouseID(MapOwnerID)
                self:SetIsInDoor()

                if self.IndoorHouseID > 0 then
                    if self.OwnHouseID == self.IndoorHouseID 
                            or self.IndoorHouseID == self.SharedHouseID 
                            or self.IndoorHouseID == self.ArmyHouseID
                            or self.IndoorHouseID == self.ArmyPersonalHouseID then
                        self.HouseID = self.IndoorHouseID
                        self:SendHouseDepotReq() -- TODO: 放到SendPullDecorateReq回包后处理
                    end
    
                    self:SendPullDecorateReq({self.IndoorHouseID}, self.Region, true)
                end
            end
        end
    end
end

--- 部队私人房间数据无法保证在OnPWorldMapEnter前获取到完整数据，添加一个方法，刷新一下HouseID
function HousingMgr:RefreshHouseID()
    if self:IsInDoor() then
        if self.HouseID == 0 and self.IndoorHouseID > 0 then
            if self.IndoorHouseID == self.ArmyPersonalHouseID or self.IndoorHouseID == self.ArmyHouseID then
                self.HouseID = self.IndoorHouseID
                self:SendHouseDepotReq() -- TODO: 放到SendPullDecorateReq回包后处理
                self:SendPullDecorateReq({self.IndoorHouseID}, self.Region, true)
            end
        end
    else
        self:EnterHouseBlock(self.CurrentHousingBlockId)
    end
end

