--region 房屋入口

function HousingMgr:AddBlockToWaitingList(BlockID)
    table.insert(self.EntranceWaitingList, BlockID)
    if self.HouseEntranceTimer == nil then
        self.HouseEntranceTimer = _G.TimerMgr:AddTimer(self, self.OnHouseEntranceTimer, 1, 1)
    end
end

-- GetDoorTargetPosition 需等待c++数据准备好&&sg加载完，才能正常获取坐标，故模仿端游采用轮询方案
function HousingMgr:OnHouseEntranceTimer()
    if (#self.EntranceWaitingList == 0) and (self.HouseEntranceTimer ~= nil) then
        _G.TimerMgr:CancelTimer(self.HouseEntranceTimer)
        self.HouseEntranceTimer = nil
        return
    end

    local HousingMgrInstance = UHousingMgr:Get()
    if HousingMgrInstance then
        for i = #self.EntranceWaitingList, 1, -1 do -- TODO 改为异步处理，减少单帧耗时
            local BlockID = self.EntranceWaitingList[i]
            local HouseID = self.BlockToHouseIDMap[BlockID]
            if self:CreateEntranceEObj_Internal(BlockID, HouseID) then
                table.remove(self.EntranceWaitingList, i)
            end
        end
    end
end

function HousingMgr:CreateEntranceEObj_Internal(BlockID, HouseID)
    print("HousingMgr:CreateEntranceEObj_Internal BlockID:", BlockID, " HouseID:", HouseID)
    if (BlockID == nil) or (HouseID == nil) then return false end

    local HousingMgrInstance = UHousingMgr:Get()
    local Pos = HousingMgrInstance:GetDoorTargetPosition(BlockID - 1) -- c++ BlockID从0起

    local bRet = (Pos ~= ZeroVector)
    if bRet then
        local EntityID = _G.UE.UActorManager.Get():CreateClientActor(_G.UE.EActorType.EObj, 0,
            ENTRANCE_EOBJID, Pos, ZeroRotator)
        self.HouseEntranceEObjMap[HouseID] = EntityID
    end

    print("HousingMgr:CreateEntranceEObj_Internal Pos:", Pos.X, Pos.Y, Pos.Z)
    return bRet
end

function HousingMgr:CheckNeedChangeEntranceEObj(Basic, Roommate)
    local HouseID = Basic.HouseID

    local DecorateDataManager = self.HouseDecorateDataManager[HouseID]
    local bHasData = DecorateDataManager and DecorateDataManager[ProtoRes.HouseRegionType.HouseRegionType_Yard]
    if not bHasData then return end

    local bHasEntrance = (self.HouseEntranceEObjMap[HouseID] ~= nil)
    local bCanVisit = _G.HouseLandMgr.GetVisitPrivile(Basic.OwnerID, Basic.VisitSetting, Roommate,
        ProtoCS.HouseVisitSettingType.HouseVisitSettingType_Enter, Basic.HouseType)

    if bCanVisit ~= bHasEntrance then
        if bCanVisit then
            self:CheckCreateEntranceEObj(Basic, Roommate, true)
        else
            self:DestroyHouseEntranceEObj(HouseID)
        end
    end
end

function HousingMgr:CheckCreateEntranceEObj(Basic, Roommate, bNoCheckVisit)
    local HouseID = Basic.HouseID
    if self.HouseEntranceEObjMap[HouseID] ~= nil then
        return
    end

    local DecorateDataManager = self.HouseDecorateDataManager[HouseID]
    local bHasData = DecorateDataManager and DecorateDataManager[ProtoRes.HouseRegionType.HouseRegionType_Yard]

    if not bHasData then return end

    local bCanVisit = bNoCheckVisit or _G.HouseLandMgr.GetVisitPrivile(Basic.OwnerID, Basic.VisitSetting, Roommate,
        ProtoCS.HouseVisitSettingType.HouseVisitSettingType_Enter, Basic.HouseType)

    if not bCanVisit then return end

    local BlockID = DecorateDataManager[ProtoRes.HouseRegionType.HouseRegionType_Yard].Addr.Number
    if not self:CreateEntranceEObj_Internal(BlockID, HouseID) then
        self:AddBlockToWaitingList(BlockID)
    end
end

function HousingMgr:CreateHouseEntranceEObj(HouseID)
    local EntityID = self.HouseEntranceEObjMap[HouseID]
    if EntityID ~= nil then
        local EObjActor = ActorUtil.GetActorByEntityID(EntityID)
        if EObjActor ~= nil then
            return
        end
        self.HouseEntranceEObjMap[HouseID] = nil
    end
    _G.HouseInfoMgr:QueryHouseDetail(HouseID, function(Basic, Roommate)
        self:CheckCreateEntranceEObj(Basic, Roommate, false)
    end)
end

function HousingMgr:DestroyHouseEntranceEObj(HouseID)
    local EntityID = self.HouseEntranceEObjMap[HouseID]
    if EntityID ~= nil then
        local EObjActor = ActorUtil.GetActorByEntityID(EntityID)
        if EObjActor ~= nil then
            _G.UE.UActorManager.Get():RemoveClientActor(EntityID)
        end
        self.HouseEntranceEObjMap[HouseID] = nil
        return
    end

    if #self.EntranceWaitingList == 0 then return end

    local DecorateDataManager = self.HouseDecorateDataManager[HouseID]
    if (DecorateDataManager ~= nil) and (DecorateDataManager[ProtoRes.HouseRegionType.HouseRegionType_Yard] ~= nil) then
        local BlockID = DecorateDataManager[ProtoRes.HouseRegionType.HouseRegionType_Yard].Addr.Number
        for i = #self.EntranceWaitingList, 1, -1 do
            if (BlockID == self.EntranceWaitingList[i]) then
                table.remove(self.EntranceWaitingList, i)
                break
            end
        end
    end
end

--更新

--更新公共区域外形
local function MakeCppHouseData(DecorateData)
    local HouseData = ZoneProtoDownGAME_House()
    HouseData.Block = DecorateData.Addr.Number
    HouseData.Size = HousingMgr:GetHouseSize(DecorateData.HouseID)
    HouseData.ExteriorIds = _G.UE.TArray(_G.UE.int32)
    HouseData.Colors = _G.UE.TArray(_G.UE.int32)

    local ExteriorIds = {}

    for _ = 1, 8 do
        table.insert(ExteriorIds, 0)
        HouseData.Colors:Add(0)
    end

    for _, Floor in pairs(DecorateData.DoUp.Floors) do
        for _, Entity in ipairs(Floor.Entities) do
            if Entity.GID > 0 then
                local Pos = HouseUtil.GetOutDoorPosToIndex(Entity.Pos)
                ExteriorIds[Pos] = Entity.Key
            end
        end
    end

    for _, Id in ipairs(ExteriorIds) do
        HouseData.ExteriorIds:Add(Id)
    end

    return HouseData
end

function HousingMgr:UpdateHousePublicSceneHouse(AreaBlockBegin, AreaBlockEnd)
    local ExteriorData = ZoneProtoDownGAME_HouseList()
    ExteriorData.Area = self.CurrentHousingAreaSubId
    ExteriorData.LandSetId = 0
    ExteriorData.MansionStatus = 0
    
    local ValidBlocks = {}
    for _, v in pairs(self.HouseDecorateDataManager) do
        local DecorateData = v[ProtoRes.HouseRegionType.HouseRegionType_Yard]

        -- 部队成员房间不创建
        if DecorateData.HouseType and DecorateData.HouseType ~= ProtoCS.HouseType.HouseType_HouseType_GroupMemberRoom then
            if DecorateData.Addr and DecorateData.Addr.EstateID == self.CurrentHousingEstateID and
                    DecorateData.Addr.Area == self.CurrentHousingAreaId then
                local BlockID = DecorateData.Addr.Number

                if BlockID >= AreaBlockBegin and BlockID <= AreaBlockEnd then
                    _G.FLOG_INFO("HousingMgr:OnUpdateHouse Create HouseID = : %s", tostring(DecorateData.HouseID))
                    local HouseData = MakeCppHouseData(DecorateData)
                    ExteriorData.Houses:Add(HouseData)
                    ValidBlocks[BlockID] = true
                end
            end
        end
    end

    for Block = AreaBlockBegin, AreaBlockEnd do
        if not ValidBlocks[Block] then
            local ClearData = ZoneProtoDownGAME_House()
            ClearData.Block = Block
            ClearData.Size = 0
            for _ = 1, 8 do
                ClearData.ExteriorIds:Add(0)
                ClearData.Colors:Add(0)
            end
            ExteriorData.Houses:Add(ClearData)
        end
    end

    local HousingMgrInstance = UHousingMgr:Get()
    if HousingMgrInstance ~= nil then
        HousingMgrInstance:OnReceiveHouseList(ExteriorData)
    end
end

function HousingMgr:UpdateHousePublicSceneHouse_Single(HouseID)
    local ExteriorData = ZoneProtoDownGAME_HouseList()
    ExteriorData.Area = self.CurrentHousingAreaSubId
    ExteriorData.LandSetId = 0
    ExteriorData.MansionStatus = 0

    local DecorateData = self.HouseDecorateDataManager[HouseID][ProtoRes.HouseRegionType.HouseRegionType_Yard]
    
    if DecorateData.HouseType and DecorateData.HouseType ~= ProtoCS.HouseType.HouseType_HouseType_GroupMemberRoom then
        local HouseData = MakeCppHouseData(DecorateData)
        ExteriorData.Houses:Add(HouseData)

        local HousingMgrInstance = UHousingMgr:Get()
        if HousingMgrInstance ~= nil then
            HousingMgrInstance:OnReceiveHouseList(ExteriorData)
        end
        
    end
end

--拉取关卡外装相关信息(c++代码里回调)
function HousingMgr:UpdateExteriorHouse(Params)
    if self.Region == ProtoRes.HouseRegionType.HouseRegionType_Yard then
        HousingMgr:SendPullEstateHouseReq()
    end
end

function HousingMgr:IsHouseBuildInBlock(EstateID,Area,Block)
    local HouseID = 0
    for k,v in pairs(self.HouseDecorateDataManager) do
        local HouseInfo =  self.HouseDecorateDataManager[k][ProtoRes.HouseRegionType.HouseRegionType_Yard]
        if HouseInfo ~= nil then
            if HouseInfo.Addr == nil then -- 只输出日志，上线前暂不处理流程，方便发现问题
                _G.FLOG_ERROR("HousingMgr:IsHouseBuildInBlock Addr is nil, HouseInfo=%s", _G.TableToString(HouseInfo))
            end
            if HouseInfo.Addr.EstateID == EstateID and HouseInfo.Addr.Area == Area and HouseInfo.Addr.Number == Block then
                HouseID = k
                break
            end
        end
    end
    return HouseID
end

function HousingMgr:CanEditCenterLight(HouseID)
    local HouseSize = self:GetHouseSize(HouseID)
    return HouseSize == HouseCommon.HouseSize.HOUSE_SIZE_L
end

