--开始编辑
function HousingMgr:SendHouseBeginEditReq()
    local MsgID = CS_CMD.CS_CMD_HOUSE
    local SubMsgID = SUB_MSG_ID.CS_SUBMSGID_HOUSE_BEGIN_EDIT

    local MsgBody = {}
    MsgBody.SubCmd = SubMsgID
    MsgBody.BeginEdit = { HouseID = self.HouseID,Region = self.Region }

    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody)
end

function HousingMgr:RspHouseBeginEdit(MsgBody)
    if _G.UIViewMgr:IsViewVisible(UIViewID.MainPanel) then
        if self.InDoor then
            self.HouseModel = HouseCommon.HouseModel.FurnitureModel
        else
            self.HouseModel = HouseCommon.HouseModel.YardModel
        end

        --关闭主界面
        _G.UIViewMgr:HideView(UIViewID.MainPanel)
        --打开HOUSE主界面
        _G.UIViewMgr:ShowView(UIViewID.HouseMainPanelView)

        local HousingMgrInstance = UHousingMgr:Get()
        if HousingMgrInstance ~= nil then
            HousingMgrInstance:BeginEditorModel()
            HousingMgrInstance:SetMountMode(false)
        end
    end
end

--结束编辑
function HousingMgr:SendHouseFinishEditReq()
    local MsgID = CS_CMD.CS_CMD_HOUSE
    local SubMsgID = SUB_MSG_ID.CS_SUBMSGID_HOUSE_FINISH_EDIT

    local MsgBody = {}
    MsgBody.SubCmd = SubMsgID
    MsgBody.FinishEdit = { HouseID = self.HouseID,Region = self.Region }

    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody)
end

function HousingMgr:RspHouseFinishEdit(MsgBody)
    self.HouseModel = HouseCommon.HouseModel.None

    _G.UIViewMgr:HideView(UIViewID.HouseMainPanelView)
    _G.UIViewMgr:ShowView(UIViewID.MainPanel)

    local HousingMgrInstance = UHousingMgr:Get()
    if HousingMgrInstance ~= nil then
        HousingMgrInstance:EndEditorModel()
        HousingMgrInstance:SetLayoutEditMode(HouseCommon.eLayoutEditMode.LAYOUTEDIT_MODE_INVALID)
    end
end

--拉取仓库
function HousingMgr:SendHouseDepotReq(InHouseID, InRegion)
    local MsgID = CS_CMD.CS_CMD_HOUSE
    local SubMsgID = SUB_MSG_ID.CS_SUBMSGID_HOUSE_GET_DEPOT

    local MsgBody = {}
    MsgBody.SubCmd = SubMsgID
    MsgBody.GetDepot = { HouseID = InHouseID or self.HouseID,Region = InRegion or self.Region }

    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody,0,self.HouseID)
end

function HousingMgr:RspHouseDepot(MsgBody)
    local HouseID = MsgBody.GetDepot.HouseID
    local RegionType = MsgBody.GetDepot.Region
    local Depot = self:GetDepotData(HouseID, RegionType)

    -- 更新仓库数据
    Depot.Capacity = MsgBody.GetDepot.Capacity
    Depot.ItemList = MsgBody.GetDepot.ItemList

    -- 处理默认容量
    local RegionCfg = self:GetHouseRegionCfg()
    if Depot.Capacity == 0 and RegionCfg then
        Depot.Capacity = RegionCfg.DepotSize
    end
end

--拉取房屋的信息
function HousingMgr:SendPullDecorateReq(HIDs, InRegion, bNeedDecorate)
    local MsgID = CS_CMD.CS_CMD_HOUSE
    local SubMsgID = SUB_MSG_ID.CS_SUBMSGID_HOUSE_PULL_DECORATE

    local MsgBody = {}
    MsgBody.SubCmd = SubMsgID
    MsgBody.PullDecorate = { Region = InRegion or self.Region, HouseIDs = HIDs }
    
    self.bNeedDecorate = self.bNeedDecorate or bNeedDecorate
    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody)
end

function HousingMgr:RespPullDecorate(MsgBody)
    for k,v in pairs(MsgBody.PullDecorate.DecorateInfos) do
        ---- 房屋拆除 未回收土地时会保留信息 但房屋实际已经拆了
        if not v.IsDestoried then
            self:UpdateHouseDecorateData(v.HouseID, MsgBody.PullDecorate.Region, v)
            
            -- 有些情况会多次请求，但是只需要组装一次
            if self.bNeedDecorate and v.HouseID == self.IndoorHouseID and MsgBody.PullDecorate.Region == ProtoRes.HouseRegionType.HouseRegionType_Room then
                self.bNeedDecorate = false
                self:CreateFurnitureObjectIDToIndexMap()

                for x,y in pairs(v.Furniture.Entities) do
                    self.FurnitureObjectIDToIndexMap[x] = y.GID
                end

                --放置家具
                self:PlaceIndoorFurnitureList(v.Furniture)

                --室内则直接变化当前房间的家装效果(更新房屋灯光)
                if #v.Setting.Settings > 0 then
                    for Key,Setting in pairs(v.Setting.Settings) do
                        if Setting.Typ == ProtoCS.HouseSettingType.HouseSettingType_Light then
                            if self.HouseID == v.HouseID then
                                self:SetLightPower(Setting.Value)
                            end

                            self:SetHouseLightPower(Setting.Value)
                        end
                    end
                else
                    if self.HouseID == v.HouseID then
                        self:SetLightPower(0)
                    end

                    self:SetHouseLightPower(0)
                end

                --这里要变化外观
                _G.EventMgr:SendEvent(EventID.RefreshDecorateEffect,{HouseID = v.HouseID,Region = MsgBody.PullDecorate.Region})
            end
    
            --断线重连时要判断如果当前正在编辑当前房屋，如果编辑者已经变了，则马上退出所有界面
            if self.HouseID > 0 and self.HouseID == v.HouseID then
                local RoleID = MajorUtil.GetMajorRoleID()
                local CurTime = TimeUtil.GetServerTime()
                if v.CurDecorator.RoleID ~= RoleID or CurTime - v.CurDecorator.BeginTime > 60 then
                    _G.EventMgr:SendEvent(EventID.ChangeHouseEditRole)
    
                    local HousingMgrInstance = UHousingMgr:Get()
                    if HousingMgrInstance ~= nil then
                        HousingMgrInstance:EndEditorModel()
                    end
                end
            end
        end
    end
end

--装修
function HousingMgr:SendDecorateReq(DecorateOps, ChangePosOps)
    local MsgID = CS_CMD.CS_CMD_HOUSE
    local SubMsgID = SUB_MSG_ID.CS_SUBMSGID_HOUSE_DO_UP_SET

    local Ops = {}
    local GlobalOps = {}
    local ChangePoses = {}

    if DecorateOps then
        for _, DecorateOp in ipairs(DecorateOps) do
            local ServerFloor = HouseUtil.ConvertClientFloorToServerFloor(DecorateOp.Floor)

            local Operation = {
                Floor = ServerFloor,
                Pos = DecorateOp.Pos,
                BagType = DecorateOp.BagType,
                EntityKey = DecorateOp.EntityKey
            }

            if DecorateOp.Item then
                Operation.Item = {
                    ItemGid = DecorateOp.Item.GID,
                    ItemResID = DecorateOp.Item.ResID,
                }
            end

            -- 判断是否为全局装潢（房间中心灯）
            if DecorateOp.Pos == ProtoRes.HouseDoUpPos.HouseDoUpPos_RoomCenterLight then
                table.insert(GlobalOps, Operation)
            else
                table.insert(Ops, Operation)
            end
        end
    end

    if ChangePosOps then
        for _, ChangePosOp in ipairs(ChangePosOps) do
            local Operation = {
                Floor = HouseUtil.ConvertClientFloorToServerFloor(ChangePosOp.Floor),
                Pos = ChangePosOp.Pos,
                BagType = ChangePosOp.BagType, -- TODO:
                --EntityKey = DecorateOp.EntityKey
            }
            table.insert(Ops, Operation)
            
            local Operation2 = {
                Floor = HouseUtil.ConvertClientFloorToServerFloor(ChangePosOp.Floor),
                Pos = ChangePosOp.Pos,
                FromFloor = HouseUtil.ConvertClientFloorToServerFloor(ChangePosOp.FromFloor),
                FromPos = ChangePosOp.FromPos
            }
            table.insert(ChangePoses, Operation2)
        end
    end

    local MsgBody = {
        SubCmd = SubMsgID,
        DoUpSet = {
            HouseID = self.HouseID,
            Region = self.Region,
            Ops = Ops,
            GlobalOps = GlobalOps,
            ChangePoses = ChangePoses
        }
    }

    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody)
end

function HousingMgr:RespDoUpSet(MsgBody)
    if MsgBody.DoUpSet.HouseID ~= self.HouseID then
        return
    end

    local function SendDecorateEvent()
        _G.EventMgr:SendEvent(EventID.SaveDecorateSucc)
        _G.EventMgr:SendEvent(EventID.RefreshDecorateEffect, {
            HouseID = MsgBody.DoUpSet.HouseID,
            Region = MsgBody.DoUpSet.Region
        })
    end

    local HouseDecorateData = self:GetCurHouseDecorateData()
    if not HouseDecorateData or not HouseDecorateData.Floors then
        SendDecorateEvent()
        return
    end

    -- 分离操作类型
    local RemoveOps = {}
    local AddOps = {}
    local GlobalRemoveOps = {}
    local GlobalAddOps = {}
    local ChangePosOps = MsgBody.DoUpSet.ChangePoses or {}

    -- 分离普通装潢操作
    for _, Op in ipairs(MsgBody.DoUpSet.Ops) do
        if Op.Item == nil then
            table.insert(RemoveOps, Op)
        else
            table.insert(AddOps, Op)
        end
    end

    -- 分离全局装潢操作
    for _, Op in ipairs(MsgBody.DoUpSet.GlobalOps or {}) do
        if Op.Item == nil then
            table.insert(GlobalRemoveOps, Op)
        else
            table.insert(GlobalAddOps, Op)
        end
    end

    -- 处理装潢操作
    local function ProcessDoUpSetRspOne(RspOp, bGlobalOps)
        local Floor = HouseUtil.ConvertServerFloorToClientFloor(RspOp.Floor)
        local HDD = HouseDecorateData
        local CliOps = nil

        if bGlobalOps then
            if not HDD.Global then return end
            local FloorCommon = HouseCommon.FloorCategory.FLOOR_CATEGORY_COMMON
            CliOps = { [FloorCommon] = { Entities = HDD.Global.Entities, Floor = FloorCommon } }
        else
            if not HDD.Floors then return end
            CliOps = HDD.Floors
        end

        if RspOp.BagType == ProtoCS.HouseUseBagType.HouseUseBagType_RoleBag or
                RspOp.BagType == ProtoCS.HouseUseBagType.HouseUseBagType_HouseDepot then
            for k, v in pairs(CliOps) do
                if v.Floor == Floor then
                    for x, Entity in ipairs(v.Entities) do
                        if Entity.Pos == RspOp.Pos then
                            _G.EventMgr:SendEvent(EventID.DecorateSlotUpdate, {
                                Type = HouseCommon.HouseItemUpdateType.RemoveDecorSlotItem,
                                Item = { GID = Entity.GID },
                                Pos = RspOp.Pos,
                                Floor = Floor
                            })
                            table.remove(v.Entities, x)
                            break
                        end
                    end
                end
            end
        end
    end

    -- 处理添加操作
    local function ProcessAddOp(RspOp, bGlobalOps)
        local Floor = HouseUtil.ConvertServerFloorToClientFloor(RspOp.Floor)
        local HDD = HouseDecorateData
        local CliOps = nil

        if bGlobalOps then
            if not HDD.Global then return end
            local FloorCommon = HouseCommon.FloorCategory.FLOOR_CATEGORY_COMMON
            CliOps = { [FloorCommon] = { Entities = HDD.Global.Entities, Floor = FloorCommon } }
        else
            if not HDD.Floors then return end
            CliOps = HDD.Floors
        end

        if RspOp.BagType == ProtoCS.HouseUseBagType.HouseUseBagType_RoleBag or
                RspOp.BagType == ProtoCS.HouseUseBagType.HouseUseBagType_HouseDepot then
            for k, v in pairs(CliOps) do
                if v.Floor == Floor then
                    local Exist = false
                    local InsertIndex = nil
                    
                    for x, Entity in ipairs(v.Entities) do
                        if Entity.Pos == RspOp.Pos then
                            Entity.Key = RspOp.Entity.Key
                            Entity.GID = RspOp.Entity.GID
                            Entity.Attr = RspOp.Entity.Attr
                            Exist = true
                            break
                        end

                        -- 记录第一个大于目标位置的位置索引
                        if not InsertIndex and Entity.Pos > RspOp.Pos then
                            InsertIndex = x
                        end
                    end

                    if not Exist then
                        local NewEntity = {
                            Key = RspOp.Entity.Key,
                            GID = RspOp.Entity.GID,
                            Attr = RspOp.Entity.Attr,
                            Pos = RspOp.Pos,
                            Floor = Floor
                        }
                        
                        if InsertIndex then
                            -- 在找到的位置插入
                            table.insert(v.Entities, InsertIndex, NewEntity)
                        else
                            -- 如果没有更大的位置，添加到末尾
                            table.insert(v.Entities, NewEntity)
                        end
                    end
                end
            end
        end
    end

    -- 处理位置移动操作
    local function ProcessChangePosOp(ChangePosOp)
        local FromFloor = HouseUtil.ConvertServerFloorToClientFloor(ChangePosOp.FromFloor)
        local ToFloor = HouseUtil.ConvertServerFloorToClientFloor(ChangePosOp.Floor)

        local SourceEntity = nil

        -- 查找源位置的装潢实体
        for _, FloorData in ipairs(HouseDecorateData.Floors) do
            if FloorData.Floor == FromFloor then
                for i, Entity in ipairs(FloorData.Entities) do
                    if Entity.Pos == ChangePosOp.FromPos then
                        SourceEntity = Entity
                        break
                    end
                end
                if SourceEntity then break end
            end
        end

        -- 如果找到源实体，移动到目标位置
        if SourceEntity then
            -- 添加到目标楼层
            for _, FloorData in ipairs(HouseDecorateData.Floors) do
                if FloorData.Floor == ToFloor then
                    local Exist = false
                    local InsertIndex = nil
                    for i, Entity in ipairs(FloorData.Entities) do
                        if Entity.Pos == ChangePosOp.Pos then
                            Entity.Key = SourceEntity.Key
                            Entity.GID = SourceEntity.GID
                            Entity.Attr = SourceEntity.Attr
                            Exist = true
                            break
                        end

                        if not InsertIndex and Entity.Pos > ChangePosOp.Pos then
                            InsertIndex = i
                        end
                    end
                    
                    if not Exist then
                        local NewEntity = {
                            Key = SourceEntity.Key,
                            GID = SourceEntity.GID,
                            Attr = SourceEntity.Attr,
                            Pos = ChangePosOp.Pos,
                            Floor = ToFloor
                        }
                        if InsertIndex then
                            table.insert(FloorData.Entities, InsertIndex, NewEntity)
                        else
                            table.insert(FloorData.Entities, NewEntity)
                        end
                    end
                end
            end
        end
    end

    -- 第一步：执行卸载操作
    for _, Op in ipairs(RemoveOps) do
        ProcessDoUpSetRspOne(Op, false) -- 普通卸载
    end

    -- 第二步：执行位置交换操作
    for _, ChangePosOp in ipairs(ChangePosOps) do
        ProcessChangePosOp(ChangePosOp)
    end

    -- 第三步：执行添加操作
    for _, Op in ipairs(AddOps) do
        ProcessAddOp(Op, false) -- 普通添加
    end

    -- 处理全局操作（卸载和添加）
    for _, Op in ipairs(GlobalRemoveOps) do
        ProcessDoUpSetRspOne(Op, true) -- 全局卸载
    end

    for _, Op in ipairs(GlobalAddOps) do
        ProcessAddOp(Op, true) -- 全局添加
    end

    SendDecorateEvent()
end


--场景内广播装修结果
function HousingMgr:NotifyDoUpSetBc(MsgBody)
    local DoUpSetBc = MsgBody and MsgBody.DoUpSetBc
    if not DoUpSetBc then return end

    -- 排除当前玩家操作
    local MajorRoleID = MajorUtil.GetMajorRoleID()
    if MajorRoleID == DoUpSetBc.OpRoleID then return end

    local HouseData = self.HouseDecorateDataManager[DoUpSetBc.HouseID]
    if not HouseData then return end

    local RegionData = HouseData[DoUpSetBc.Region]
    if not RegionData or not RegionData.DoUp then return end

    if RegionData.DoUp.Floors then
        for _, NewEntity in ipairs(DoUpSetBc.Entities) do
            local TargetFloor = HouseUtil.ConvertServerFloorToClientFloor(NewEntity.Floor)

            -- 查找目标楼层
            for _, FloorData in ipairs(RegionData.DoUp.Floors) do
                if FloorData.Floor == TargetFloor then
                    local EntityFound = false

                    -- 查找相同位置的装潢
                    for _, ExistingEntity in ipairs(FloorData.Entities) do
                        if ExistingEntity.Pos == NewEntity.Pos then
                            -- 更新现有装潢
                            ExistingEntity.Key = NewEntity.Key
                            ExistingEntity.GID = NewEntity.GID
                            ExistingEntity.Attr = NewEntity.Attr
                            EntityFound = true
                            break
                        end
                    end

                    -- 如果没找到，添加新装潢
                    if not EntityFound then
                        table.insert(FloorData.Entities, NewEntity)
                    end

                    break
                end
            end
        end
    end

    -- 处理全局装潢数据
    if RegionData.DoUp.Global and DoUpSetBc.GlobalEntities then
        for _, NewEntity in ipairs(DoUpSetBc.GlobalEntities) do
            local EntityFound = false

            -- 查找相同位置的全局装潢
            for _, ExistingEntity in ipairs(RegionData.DoUp.Global.Entities) do
                if ExistingEntity.Pos == NewEntity.Pos then
                    -- 更新现有全局装潢
                    ExistingEntity.Key = NewEntity.Key
                    ExistingEntity.GID = NewEntity.GID
                    ExistingEntity.Attr = NewEntity.Attr
                    EntityFound = true
                    break
                end
            end

            -- 如果没找到，添加新全局装潢
            if not EntityFound then
                table.insert(RegionData.DoUp.Global.Entities, NewEntity)
            end
        end
    end

    -- 刷新外观
    _G.EventMgr:SendEvent(EventID.RefreshDecorateEffect, {
        HouseID = DoUpSetBc.HouseID,
        Region = DoUpSetBc.Region
    })
end

