function HousingMgr:RespSetSetting(MsgBody)
    if MsgBody.SetSetting.HouseID == self.HouseID then
        for k,v in pairs(MsgBody.SetSetting.Settings) do
            if v.Typ == ProtoCS.HouseSettingType.HouseSettingType_Light then
                self:SetLightPower(v.Value)
                self:SetHouseLightPower(v.Value)
            end
        end
    end
end

function HousingMgr:NotifySetSettingBc(MsgBody)
    for Key,Value in pairs(self.HouseDecorateDataManager) do
        if Key == MsgBody.SetSettingBc.HouseID then
            --这里只更新变化值，如果这个数据都不存在，则通过拉全量的方式来处理
            local DecorateData = self.HouseDecorateDataManager[Key][MsgBody.SetSettingBc.Region]
            if DecorateData ~= nil then
                if DecorateData.Setting ~= nil then
                    DecorateData.Setting.Settings = MsgBody.SetSettingBc.Settings

                    for _,v in pairs(MsgBody.SetSettingBc.Settings) do
                        if v.Typ == ProtoCS.HouseSettingType.HouseSettingType_Light then
                            self:SetHouseLightPower(v.Value)
                        end
                    end
                end
            end
        end
    end
end

