--布置家具
function HousingMgr:SendPutFurnitureReq(BagType,Item,Pos,Dir,Key)
    local MsgID = CS_CMD.CS_CMD_HOUSE
    local SubMsgID = SUB_MSG_ID.CS_SUBMSGID_HOUSE_PUT_FURNITURE

    local MsgBody = {}
    MsgBody.SubCmd = SubMsgID
    MsgBody.PutFurniture = { HouseID = self.HouseID,Region = self.Region,BagType = BagType,Item = {ItemGid = Item.GID,ItemResID = Item.ResID,Num = 1},Pos = {X = Pos.X,Y = Pos.Y,Z = Pos.Z,Yaw = Dir},EntityKey = Key}

    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody,0,self.HouseID)
end

function HousingMgr:RespPutFurniture(MsgBody)
    local AppendBlockID = 0
    local ErrCode = MsgBody.ErrorCode

    local HousingMgrInstance = UHousingMgr:Get()
    if HousingMgrInstance ~= nil then
        if ErrCode == nil or ErrCode == 0 then
            HousingMgrInstance:OnHousingObjectPlaced(true)
        else
            HousingMgrInstance:OnHousingObjectPlaced(false)
            return
        end
    end

    local Entity = MsgBody.PutFurniture.Entity
    for Key,Value in pairs(self.HouseDecorateDataManager) do
        if Key == MsgBody.PutFurniture.HouseID then
            local DecorateData = self.HouseDecorateDataManager[Key][MsgBody.PutFurniture.Region]
            if DecorateData ~= nil then
                if DecorateData.Furniture ~= nil then
                    table.insert(DecorateData.Furniture.Entities,Entity)
                end

                --庭具才会有blockID
                if MsgBody.PutFurniture.Region == ProtoRes.HouseRegionType.HouseRegionType_Yard then
                    AppendBlockID = DecorateData.Addr.Number

                    local fixIndex = 1
                    local AreaBlockBegin = self.CurrentHousingAreaSubId == 1 and 1 or 31
                    for i=AreaBlockBegin,AppendBlockID-1 do
                        local Size = self:FindLandBlockSize(self.CurrentHousingEstateID,i)
                        if Size == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_S then
                            fixIndex = fixIndex + 20
                        elseif Size == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_M then
                            fixIndex = fixIndex + 30
                        elseif Size == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_L then
                            fixIndex = fixIndex + 40
                        end
                    end

                    for f=fixIndex,#self.YardObjectIDToIndexMap do
                        if self.YardObjectIDToIndexMap[f] == 0 then
                            self.YardObjectIDToIndexMap[f] = Entity.GID
                            --这里要调用底层增加家具
                            local Furniture = ZoneProtoDownGAME_YardObject()
                            Furniture.Block = AppendBlockID
                            Furniture.YardIndex = f - fixIndex
                            Furniture.Furniture = ZoneProtoDownFurniture()
                            Furniture.Furniture.HousingBaseIDLow = Entity.Key & 0xFFFF --取低16位的值
                            Furniture.Furniture.TimelineState = 0
                            self.PickIndex = f - 1
                            Furniture.Furniture.ColorID = Entity.Attr.ColorID
                            Furniture.Furniture.Dir = Entity.Pos.Yaw
                            Furniture.Furniture.Pos = _G.UE.FVector(Entity.Pos.X,Entity.Pos.Y,Entity.Pos.Z)

                            if Entity.Attr.Data ~= nil then
                                if Entity.Attr.Status ~= nil then
                                    Furniture.Furniture.TimelineState = Entity.Attr.Status.CurStatus
                                end
                            end
                            
                            if HousingMgrInstance ~= nil then
                                HousingMgrInstance:OnReceiveYardObject(Furniture)
                                HousingMgrInstance:SetNextTargetObjIndex(Furniture.YardIndex)
                            end
                            break
                        end
                    end
                else
                    for f=1,#self.FurnitureObjectIDToIndexMap do
                        if self.FurnitureObjectIDToIndexMap[f] == 0 then
                            self.FurnitureObjectIDToIndexMap[f] = Entity.GID
                            --这里要调用底层增加家具
                            local Furniture = ZoneProtoDownGAME_Furniture()
                            Furniture.FixIndex = f - 1
                            Furniture.Furniture = ZoneProtoDownFurniture()
                            Furniture.Furniture.HousingBaseIDLow = Entity.Key & 0xFFFF --取低16位的值
                            self.PickIndex = Furniture.FixIndex
                            Furniture.Furniture.TimelineState = 0
                            Furniture.Furniture.ColorID = Entity.Attr.ColorID
                            Furniture.Furniture.Dir = Entity.Pos.Yaw
                            Furniture.Furniture.Pos = _G.UE.FVector(Entity.Pos.X,Entity.Pos.Y,Entity.Pos.Z)

                            if Entity.Attr.Data ~= nil then
                                if Entity.Attr.Food ~= nil then
                                    Furniture.Furniture.TimelineState = _G.FurnitureInteractionMgr:GetFurnitureTimelineState(Entity)
                                elseif Entity.Attr.Status ~= nil then
                                    Furniture.Furniture.TimelineState = Entity.Attr.Status.CurStatus
                                end
                            end
                            
                            if HousingMgrInstance ~= nil then
                                HousingMgrInstance:OnReceiveFurniture(Furniture)
                                HousingMgrInstance:SetNextTargetObjIndex(Furniture.FixIndex)
                            end

                            break
                        end
                    end
                end

                --_G.EventMgr:SendEvent(_G.EventID.EnterHouseFurniturePreview, {
                --    Item = { GID = Entity.GID, ResID = MsgBody.PutFurniture.Item.ItemResID },
                --    Rotate = 0,
                --    Source = HouseCommon.FurnitureSource.BagDepot
                --})
                
                -- 放置完家具后，需要清除一些操作，比如选中，点击事件释放等
                self:CancelPickObject()

                if HousingMgrInstance ~= nil then
                    HousingMgrInstance:SetMouseCancelReleased()
                    HousingMgrInstance:EndLayoutMode() -- LAYOUTEDIT_MODE_INVALID
                end
            end
        end
    end

    --删除仓库Item，背包变化走背包变化协议
    if MsgBody.PutFurniture.BagType == ProtoCS.HouseUseBagType.HouseUseBagType_HouseDepot then
        local Depot = self:GetDepotData(self.HouseID, self.Region)
        for i = #Depot.ItemList, 1, -1 do
            if Depot.ItemList[i].GID == MsgBody.PutFurniture.Item.ItemGid then
                table.remove(Depot.ItemList, i)
                break
            end
        end
    end

    local Params = {BagType = MsgBody.PutFurniture.BagType, Entity = Entity }
    _G.EventMgr:SendEvent(EventID.PutFurnitureSucc, Params)
end

function HousingMgr:NotifyPutFurnitureBc(MsgBody)
    if not MsgBody or not MsgBody.PutFurnitureBc then
        return
    end
    
    --只处理非放置角色，放置角色的变化走放置成功协议
    local MajorRoleID = MajorUtil.GetMajorRoleID()
    if MajorRoleID == MsgBody.PutFurnitureBc.OpRoleID then
        return
    end
    
    local AppendBlockID = 0
    local Entity = MsgBody.PutFurnitureBc.Entity
    for Key,Value in pairs(self.HouseDecorateDataManager) do
        if Key == MsgBody.PutFurnitureBc.HouseID then
            local DecorateData = self.HouseDecorateDataManager[Key][MsgBody.PutFurnitureBc.Region]
            if DecorateData ~= nil then
                if DecorateData.Furniture ~= nil then
                    table.insert(DecorateData.Furniture.Entities,Entity)
                end

                --庭具才会有blockID
                if MsgBody.PutFurnitureBc.Region == ProtoRes.HouseRegionType.HouseRegionType_Yard then
                    AppendBlockID = DecorateData.Addr.Number

                    local fixIndex = 1
                    local AreaBlockBegin = self.CurrentHousingAreaSubId == 1 and 1 or 31
                    for i=AreaBlockBegin,AppendBlockID-1 do
                        local Size = self:FindLandBlockSize(self.CurrentHousingEstateID,i)
                        if Size == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_S then
                            fixIndex = fixIndex + 20
                        elseif Size == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_M then
                            fixIndex = fixIndex + 30
                        elseif Size == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_L then
                            fixIndex = fixIndex + 40
                        end
                    end

                    for f=fixIndex,#self.YardObjectIDToIndexMap do
                        if self.YardObjectIDToIndexMap[f] == 0 then
                            self.YardObjectIDToIndexMap[f] = Entity.GID
                            --这里要调用底层增加家具
                            local Furniture = ZoneProtoDownGAME_YardObject()
                            Furniture.Block = AppendBlockID
                            Furniture.YardIndex = f - fixIndex
                            Furniture.Furniture = ZoneProtoDownFurniture()
                            Furniture.Furniture.HousingBaseIDLow = Entity.Key & 0xFFFF --取低16位的值
                            Furniture.Furniture.TimelineState = 0
                            self.PickIndex = f - 1
                            Furniture.Furniture.ColorID = Entity.Attr.ColorID
                            Furniture.Furniture.Dir = Entity.Pos.Yaw
                            Furniture.Furniture.Pos = _G.UE.FVector(Entity.Pos.X,Entity.Pos.Y,Entity.Pos.Z)

                            if Entity.Attr.Data ~= nil then
                                if Entity.Attr.Status ~= nil then
                                    Furniture.Furniture.TimelineState = Entity.Attr.Status.CurStatus
                                end
                            end

                            local HousingMgrInstance = UHousingMgr:Get()
                            if HousingMgrInstance ~= nil then
                                HousingMgrInstance:OnReceiveYardObject(Furniture)
                                HousingMgrInstance:SetNextTargetObjIndex(Furniture.YardIndex)
                            end
                            break
                        end
                    end
                else
                    for f=1,#self.FurnitureObjectIDToIndexMap do
                        if self.FurnitureObjectIDToIndexMap[f] == 0 then
                            self.FurnitureObjectIDToIndexMap[f] = Entity.GID
                            --这里要调用底层增加家具
                            local Furniture = ZoneProtoDownGAME_Furniture()
                            Furniture.FixIndex = f - 1
                            Furniture.Furniture = ZoneProtoDownFurniture()
                            Furniture.Furniture.HousingBaseIDLow = Entity.Key & 0xFFFF --取低16位的值
                            self.PickIndex = Furniture.FixIndex
                            Furniture.Furniture.TimelineState = 0
                            Furniture.Furniture.ColorID = Entity.Attr.ColorID
                            Furniture.Furniture.Dir = Entity.Pos.Yaw
                            Furniture.Furniture.Pos = _G.UE.FVector(Entity.Pos.X,Entity.Pos.Y,Entity.Pos.Z)

                            if Entity.Attr.Data ~= nil then
                                if Entity.Attr.Food ~= nil then
                                    Furniture.Furniture.TimelineState = _G.FurnitureInteractionMgr:GetFurnitureTimelineState(Entity)
                                elseif Entity.Attr.Status ~= nil then
                                    Furniture.Furniture.TimelineState = Entity.Attr.Status.CurStatus
                                end
                            end

                            local HousingMgrInstance = UHousingMgr:Get()
                            if HousingMgrInstance ~= nil then
                                HousingMgrInstance:OnReceiveFurniture(Furniture)
                                HousingMgrInstance:SetNextTargetObjIndex(Furniture.FixIndex)
                            end

                            break
                        end
                    end
                end
            end
        end
    end

    local Params = {HouseID = MsgBody.PutFurnitureBc.HouseID,Region = MsgBody.PutFurnitureBc.Region,Entity = MsgBody.PutFurnitureBc.Entity }
    _G.EventMgr:SendEvent(EventID.PutFurnitureBc, Params)
end

--移动家具(因为有吸附所以会移动多个)
function HousingMgr:SendMoveFurnitureReq(FurnitureList)
    local MsgID = CS_CMD.CS_CMD_HOUSE
    local SubMsgID = SUB_MSG_ID.CS_SUBMSGID_HOUSE_MOVE_FURNITURE

    local MsgBody = {}
    MsgBody.SubCmd = SubMsgID
    MsgBody.MoveFurniture = { HouseID = self.HouseID,Region = self.Region,Moves = {}}

    for _,v in pairs(FurnitureList) do
        local MoveItem = {FurnitureID = v.GID,Pos = {X = math.ceil(v.X),Y = math.ceil(v.Y),Z = math.ceil(v.Z),Yaw = math.ceil(v.Yaw)}}
        table.insert(MsgBody.MoveFurniture.Moves,MoveItem)
    end

    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody,0,self.HouseID)
end

function HousingMgr:RespMoveFurniture(MsgBody)
    if not MsgBody or not MsgBody.MoveFurniture then
        return
    end
    
    if self.HouseID == MsgBody.MoveFurniture.HouseID then
        self.PickIndex = nil
        local Furnitures = {}
        for Key,Value in pairs(self.HouseDecorateDataManager) do
            if Key == MsgBody.MoveFurniture.HouseID then
                local DecorateData = self.HouseDecorateDataManager[Key][MsgBody.MoveFurniture.Region]
                if DecorateData ~= nil then
                    if DecorateData.Furniture ~= nil then
                        for _, v in pairs(MsgBody.MoveFurniture.Moves) do
                            for _, Entity in pairs(DecorateData.Furniture.Entities) do
                                if Entity.GID == v.FurnitureID then
                                    Entity.Pos = v.Pos
                                    --庭具才会有blockID
                                    if MsgBody.MoveFurniture.Region == ProtoRes.HouseRegionType.HouseRegionType_Yard then
                                        --C++移动物品
                                        local Furniture = ZoneProtoDownGAME_HousingObjectTransform()
                                        local RecycleBlockID = DecorateData.Addr.Number
                                        local SubFixIndex =  self:FindSubFixIndex(self.CurrentHousingAreaSubId,self.CurrentHousingEstateID,RecycleBlockID,Entity.GID)
                                        Furniture.FixIndex = RecycleBlockID * 256 + SubFixIndex
                                        Furniture.Dir = v.Pos.Yaw
                                        Furniture.Pos = _G.UE.FVector(v.Pos.X,v.Pos.Y,v.Pos.Z)
                                        table.insert(Furnitures,Furniture)
                                    else
                                        local Furniture = ZoneProtoDownGAME_HousingObjectTransform()
                                        local FixIndex =  self:GetFurnitureObjectIndex(Entity.GID) - 1
                                        Furniture.FixIndex = FixIndex
                                        Furniture.Dir = v.Pos.Yaw
                                        Furniture.Pos = _G.UE.FVector(v.Pos.X,v.Pos.Y,v.Pos.Z)
                                        table.insert(Furnitures,Furniture)
                                    end

                                    break
                                end
                            end
                        end
                        break
                    end
                end
            end
        end

        local HousingMgrInstance = UHousingMgr:Get()
        if HousingMgrInstance ~= nil then
            for k,v in pairs(Furnitures) do
                HousingMgrInstance:OnReceiveHousingObjectTransform(v)
            end
        end

        local Params = {HouseID = MsgBody.MoveFurniture.HouseID,Region = MsgBody.MoveFurniture.Region,Move = MsgBody.MoveFurniture.Moves}
        _G.EventMgr:SendEvent(EventID.MoveFurnitureSucc, Params)
    end
end

function HousingMgr:NotifyMoveFurnitureBc(MsgBody)
    local MoveData = MsgBody and MsgBody.MoveFurnitureBc
    if not MoveData then return end

    if MajorUtil.GetMajorRoleID() == MoveData.OpRoleID then return end

    local HouseDecorateManager = self.HouseDecorateDataManager[MoveData.HouseID]
    if not HouseDecorateManager then return end

    local RegionData = HouseDecorateManager[MoveData.Region]
    if not RegionData or not RegionData.Furniture then return end

    local FurnitureTransforms = {}
    local Entities = RegionData.Furniture.Entities
    local IsYardRegion = (MoveData.Region == ProtoRes.HouseRegionType.HouseRegionType_Yard)
    local IsCurrentHouse = (self.IndoorHouseID == MoveData.HouseID)

    for _, MoveInfo in ipairs(MoveData.Moves) do
        for _, Entity in ipairs(Entities) do
            if Entity.GID == MoveInfo.FurnitureID then
                -- 更新位置
                Entity.Pos = MoveInfo.Pos

                -- 准备C++同步数据
                if IsYardRegion or IsCurrentHouse then
                    local Transform = ZoneProtoDownGAME_HousingObjectTransform()
                    Transform.Dir = MoveInfo.Pos.Yaw
                    Transform.Pos = _G.UE.FVector(Entity.Pos.X, Entity.Pos.Y, Entity.Pos.Z)

                    if IsYardRegion then
                        -- 庭院家具处理
                        local RecycleBlockID = RegionData.Addr.Number
                        local SubFixIndex = self:FindSubFixIndex(
                                self.CurrentHousingAreaSubId,
                                self.CurrentHousingEstateID,
                                RecycleBlockID,
                                Entity.GID
                        )
                        Transform.FixIndex = RecycleBlockID * 256 + SubFixIndex
                    else
                        -- 室内家具处理
                        Transform.FixIndex = self:GetFurnitureObjectIndex(Entity.GID) - 1
                    end

                    table.insert(FurnitureTransforms, Transform)
                end
                break
            end
        end
    end

    local HousingMgrInstance = UHousingMgr:Get()
    if HousingMgrInstance and #FurnitureTransforms > 0 then
        for _, Transform in ipairs(FurnitureTransforms) do
            HousingMgrInstance:OnReceiveHousingObjectTransform(Transform)
        end
    end

    _G.EventMgr:SendEvent(EventID.MoveFurnitureSucc, {
        HouseID = MoveData.HouseID,
        Region = MoveData.Region,
        Move = MoveData.Moves
    })
end


--回收家具
function HousingMgr:SendBackFurnitureReq(GID,BagType)
    local MsgID = CS_CMD.CS_CMD_HOUSE
    local SubMsgID = SUB_MSG_ID.CS_SUBMSGID_HOUSE_BACK_FURNITURE

    local MsgBody = {}
    MsgBody.SubCmd = SubMsgID
    MsgBody.BackFurniture = { HouseID = self.HouseID,Region = self.Region,FurnitureID = GID,ItemTO = BagType}

    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody)
end

function HousingMgr:RespBackFurniture(MsgBody)
    local ErrCode = MsgBody.ErrorCode
    local RecycleFurnitureKey = 0

    if ErrCode ~= nil then
        return
    end

    if self.HouseID == MsgBody.BackFurniture.HouseID then
        for Key,Value in pairs(self.HouseDecorateDataManager) do
            if Key == MsgBody.BackFurniture.HouseID then
                local DecorateData = self.HouseDecorateDataManager[Key][MsgBody.BackFurniture.Region]
                if DecorateData ~= nil then
                    if DecorateData.Furniture ~= nil then
                        for i, Entity in pairs(DecorateData.Furniture.Entities) do
                            if Entity.GID == MsgBody.BackFurniture.FurnitureID then
                                RecycleFurnitureKey = Entity.Key

                                --庭具才会有blockID
                                if MsgBody.BackFurniture.Region == ProtoRes.HouseRegionType.HouseRegionType_Yard then
                                    local RecycleBlockID = DecorateData.Addr.Number
                                    local SubFixIndex =  self:FindSubFixIndex(self.CurrentHousingAreaSubId,self.CurrentHousingEstateID,RecycleBlockID,Entity.GID)
                                    local FixIndex = self:FindFixIndex(self.CurrentHousingAreaSubId,self.CurrentHousingEstateID,RecycleBlockID,Entity.GID)
                                    self.YardObjectIDToIndexMap[FixIndex] = 0
                                    --C++删除家具

                                    if self.PickIndex == FixIndex - 1 then
                                        self.PickIndex = nil
                                    end

                                    local HousingMgrInstance = UHousingMgr:Get()
                                    if HousingMgrInstance ~= nil then
                                        HousingMgrInstance:OnUnplaceYardObject(RecycleBlockID,SubFixIndex,0)
                                    end

                                else
                                    for k,v in pairs(self.FurnitureObjectIDToIndexMap) do
                                        if v == Entity.GID then
                                            if self.PickIndex == k - 1 then
                                                self.PickIndex = nil
                                            end

                                            self.FurnitureObjectIDToIndexMap[k] = 0

                                            local HousingMgrInstance = UHousingMgr:Get()
                                            if HousingMgrInstance ~= nil then
                                                HousingMgrInstance:OnUnplaceFurniture(k-1,0)
                                            end

                                            break
                                        end
                                    end
                                end

                                table.remove(DecorateData.Furniture.Entities, i)
                                _G.EventMgr:SendEvent(EventID.RemoveFurniture)
                                break
                            end
                        end
                        break
                    end
                end
            end
        end
    end
end

function HousingMgr:NotifyBackFurnitureBc(MsgBody)
    local BackData = MsgBody and MsgBody.BackFurnitureBc
    if not BackData then return end

    local MajorRoleID = MajorUtil.GetMajorRoleID()
    if MajorRoleID == BackData.OpRoleID then return end

    local HouseData = self.HouseDecorateDataManager[BackData.HouseID]
    if not HouseData then return end

    local RegionData = HouseData[BackData.Region]
    if not RegionData or not RegionData.Furniture then return end

    local Entities = RegionData.Furniture.Entities
    local RecycleFurnitureKey = 0
    local IsYardRegion = (BackData.Region == ProtoRes.HouseRegionType.HouseRegionType_Yard)
    local IsCurrentHouse = (self.IndoorHouseID == BackData.HouseID)

    -- 查找并处理回退的家具
    for Index, Entity in ipairs(Entities) do
        if Entity.GID == BackData.FurnitureID then
            RecycleFurnitureKey = Entity.Key

            if IsYardRegion then
                -- 庭院家具处理
                local RecycleBlockID = RegionData.Addr.Number
                local SubFixIndex = self:FindSubFixIndex(self.CurrentHousingAreaSubId, self.CurrentHousingEstateID, RecycleBlockID, Entity.GID)
                local FixIndex = self:FindFixIndex(self.CurrentHousingAreaSubId, self.CurrentHousingEstateID, RecycleBlockID, Entity.GID)

                self.YardObjectIDToIndexMap[FixIndex] = 0

                -- C++删除家具
                local HousingMgrInstance = UHousingMgr:Get()
                if HousingMgrInstance then
                    HousingMgrInstance:OnUnplaceYardObject(RecycleBlockID, SubFixIndex, 0)
                end
            elseif IsCurrentHouse then
                -- 室内家具处理
                for ObjectIndex, FurnitureGID in pairs(self.FurnitureObjectIDToIndexMap) do
                    if FurnitureGID == Entity.GID then
                        self.FurnitureObjectIDToIndexMap[ObjectIndex] = 0

                        local HousingMgrInstance = UHousingMgr:Get()
                        if HousingMgrInstance then
                            HousingMgrInstance:OnUnplaceFurniture(ObjectIndex - 1, 0)
                        end

                        break
                    end
                end
            end

            -- 从实体列表中移除
            table.remove(Entities, Index)
            break
        end
    end
end


--一键回收所有家具
function HousingMgr:SendBackAllFurnitureReq(BagType)
    local MsgID = CS_CMD.CS_CMD_HOUSE
    local SubMsgID = SUB_MSG_ID.CS_SUBMSGID_HOUSE_BACK_ALL_FURNITURE

    local MsgBody = {}
    MsgBody.SubCmd = SubMsgID
    MsgBody.BackAllFurniture = { HouseID = self.HouseID,Region = self.Region,ItemTO = BagType}

    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody)
end

function HousingMgr:RespBackAllFurniture(MsgBody)
    for Key,Value in pairs(self.HouseDecorateDataManager) do
        if Key == MsgBody.BackAllFurniture.HouseID then
            if self.HouseDecorateDataManager[Key][MsgBody.BackAllFurniture.Region] ~= nil then
                if self.HouseDecorateDataManager[Key][MsgBody.BackAllFurniture.Region].Furniture ~= nil then
                    self.HouseDecorateDataManager[Key][MsgBody.BackAllFurniture.Region].Furniture = {}
                end
            end
        end
    end

    if MsgBody.BackAllFurniture.Region == ProtoRes.HouseRegionType.HouseRegionType_Yard then
        for k,v in pairs(self.YardObjectIDToIndexMap) do
            --清空所有家具
            self.YardObjectIDToIndexMap[k] = 0
            --C++删除所有家具
        end
    end
end

function HousingMgr:NotifyBackAllFurnitureBc(MsgBody)
    if MsgBody.BackAllFurnitureBc.HouseID ~= self.HouseID then
        if MsgBody.BackAllFurniture.Region == ProtoRes.HouseRegionType.HouseRegionType_Yard then
            for k,v in pairs(self.YardObjectIDToIndexMap) do
                --清空所有家具
                self.YardObjectIDToIndexMap[k] = 0
                --C++删除所有家具
            end
        else
            self.FurnitureObjectIDToIndexMap = {}
        end
    end
end

