--拉取公共地图所有房屋信息
function HousingMgr:SendPullEstateHouseReq()
    local MsgID = CS_CMD.CS_CMD_HOUSE
    local SubMsgID = SUB_MSG_ID.CS_SUBMSGID_HOUSE_PULL_ESTATE_HOUSE

    local MsgBody = {}
    MsgBody.SubCmd = SubMsgID
    MsgBody.PullEstateHouse = { WorldID = _G.PWorldMgr:GetCurrWorldID(), EstateID = self.CurrentHousingEstateID, Area = self.CurrentHousingAreaId}

    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody)
end

function HousingMgr:RespPullEstateHouse(MsgBody)
    local AreaSubID = HouseUtil.GetCurrentAreaSubID()
    self:CreateYardObjectIDToIndexMap(MsgBody.PullEstateHouse.EstateID, AreaSubID)

    local Furnitures = {}
    local AreaBlockBegin = AreaSubID == 1 and 1 or 31
    local AreaBlockEnd = AreaSubID == 1 and 30 or 60

    for k,v in pairs(MsgBody.PullEstateHouse.DecorateInfos) do
        ---- 房屋拆除 未回收土地时会保留信息 但房屋实际已经拆了
        if not v.IsDestoried then
            self:UpdateHouseDecorateData(v.HouseID, ProtoRes.HouseRegionType.HouseRegionType_Yard, v)
    
            --创建服务器ID与客户端INDEX之间的映射
            local fixIndex = 1
            if v.Addr.Number >= AreaBlockBegin and v.Addr.Number <= AreaBlockEnd then
                table.insert(Furnitures,{Block = v.Addr.Number,Furniture = v.Furniture})
    
                for i=AreaBlockBegin,v.Addr.Number-1 do
                    local Size = self:FindLandBlockSize(MsgBody.PullEstateHouse.EstateID,i)
                    if Size == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_S then
                        fixIndex = fixIndex + 20
                    elseif Size == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_M then
                        fixIndex = fixIndex + 30
                    elseif Size == ProtoRes.HOUSING_SIZE_TYPE.HOUSING_SIZE_L then
                        fixIndex = fixIndex + 40
                    end
                end
    
                for _,f in pairs(v.Furniture.Entities) do
                    self.YardObjectIDToIndexMap[fixIndex] = f.GID
                    fixIndex = fixIndex + 1
                end
            end
    
            --断线重连时要判断如果当前正在编辑当前房屋，如果编辑者已经变了，则马上退出所有界面
            if self.HouseID > 0 and self.HouseID == v.HouseID then
                local RoleID = MajorUtil.GetMajorRoleID()
                local CurTime = TimeUtil.GetServerTime()
                if v.CurDecorator.RoleID ~= RoleID or CurTime - v.CurDecorator.BeginTime > 60 then
                    _G.EventMgr:SendEvent(EventID.ChangeHouseEditRole)
                end
            end
        end
    end

    --刷新地图所有房子外观
    self:UpdateHousePublicSceneHouse(AreaBlockBegin,AreaBlockEnd)

    --放置庭具
    self:PlaceYardList(Furnitures)

    -- 创建房屋入口
    for k,v in pairs(MsgBody.PullEstateHouse.DecorateInfos) do
        self:CreateHouseEntranceEObj(v.HouseID)
    end
end

--拉取角色HOUSE信息
function HousingMgr:SendPullRoleInfoReq()
    local MsgID = CS_CMD.CS_CMD_HOUSE
    local SubMsgID = SUB_MSG_ID.CS_SUBMSGID_HOUSE_PULL_ROLE_INFO

    local MsgBody = {}
    MsgBody.SubCmd = SubMsgID
    MsgBody.PullRoleInfo = {}

    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody)
end

function HousingMgr:RespPullRoleInfo(MsgBody)
    if not MsgBody or not MsgBody.PullRoleInfo then
        return
    end
    
    local OwnerHouseID = MsgBody.PullRoleInfo.HouseID or 0
    local SharedHouseID = MsgBody.PullRoleInfo.SharedHouseID or 0

    self:SetOwnHouseID(OwnerHouseID)
    self:SetSharedHouseID(SharedHouseID)

    -- 创建有效的房屋ID列表
    local ValidHouseIDs = {}
    if OwnerHouseID and OwnerHouseID > 0 then
        table.insert(ValidHouseIDs, OwnerHouseID)
    end
    if SharedHouseID and SharedHouseID > 0 then
        table.insert(ValidHouseIDs, SharedHouseID)
    end
    
    -- 请求仓库数据
    for _, HouseID in ipairs(ValidHouseIDs) do
        -- 请求房间仓库数据
        self:SendHouseDepotReq(HouseID, ProtoRes.HouseRegionType.HouseRegionType_Room)
        -- 请求庭院仓库数据
        self:SendHouseDepotReq(HouseID, ProtoRes.HouseRegionType.HouseRegionType_Yard)
    end
    
    if #ValidHouseIDs > 0 then
        self:SendPullDecorateReq(ValidHouseIDs, ProtoRes.HouseRegionType.HouseRegionType_Room)
        self:SendPullDecorateReq(ValidHouseIDs, ProtoRes.HouseRegionType.HouseRegionType_Yard)
    end

    --当前可操作的HouseID和自己没关系，这时如果在操作的话就要马上停了
    if self.HouseID > 0 then
        if self.HouseID ~= self.OwnHouseID and self.HouseID ~= self.SharedHouseID then
            _G.EventMgr:SendEvent(EventID.ChangeHouseEditRole)
        end
    end
end

--拉取主角部队个人房间
function HousingMgr:SendPullSelfGroupMemberRoom(GroupID)
    local MsgID = CS_CMD.CS_CMD_HOUSE
    local SubMsgID = SUB_MSG_ID.CS_SUBMSGID_HOUSE_PULL_SELF_GROUP_MEMBER_ROOM
    local MsgBody = {}
    MsgBody.SubCmd = SubMsgID
    MsgBody.PullSelfGroupMemberRoom = {
        GroupID = GroupID
    }
    GameNetworkMgr:SendMsg(MsgID, SubMsgID, MsgBody, 0, GroupID)
end

function HousingMgr:RspPullSelfGroupMemberRoom(MsgBody)
    local Response = MsgBody and MsgBody.PullSelfGroupMemberRoom
    local RoomDetail = Response and Response.RoomDetail
    local BasicInfo = RoomDetail and RoomDetail.Basic or {}

    if not BasicInfo.OwnerID then return end

    local HouseID = BasicInfo.HouseID or 0
    local OwnerID = BasicInfo.OwnerID or 0
    local MyRoleID = MajorUtil.GetMajorRoleID()

    if OwnerID > 0 and OwnerID == MyRoleID then
        self:SetArmyPersonalHouseID(HouseID)
        self:RefreshHouseID()
    end
end

function HousingMgr:RespEnterRoom(MsgBody)
    if not MsgBody or not MsgBody.EnterRoom then
        return
    end
    
    self:SetIndoorHouseID(MsgBody.EnterRoom.HouseID or 0)
    self:SetIsInDoor()
end

--     uint64      HouseID  = 1;
--     HouseAddr   Addr     = 2;        // 房屋位置
--     ClientDecorateInfo  DecorateInfo    = 3;
function HousingMgr:RspCreatedHouseBC(MsgBody)
    local HouseID = MsgBody.CreatedHouseBc.HouseID
    self:UpdateHouseDecorateData(HouseID, ProtoRes.HouseRegionType.HouseRegionType_Yard, MsgBody.CreatedHouseBc.DecorateInfo)
    self:UpdateHousePublicSceneHouse_Single(HouseID)
    self:CreateHouseEntranceEObj(HouseID)
end

--     uint64      HouseID  = 1;
--     HouseAddr   Addr     = 2;        // 房屋位置
function HousingMgr:RspDestroiedHouseBC(MsgBody)
    if not MsgBody or not MsgBody.DestoriedHouseBc then
        return
    end
    
    local HouseID = MsgBody.DestoriedHouseBc.HouseID or 0  --当时在哪个房就收到哪个房的houseID
    local HouseData = self.HouseDecorateDataManager[HouseID]
    if not HouseData then return end

    local RegionData = HouseData[self.Region]
    if not RegionData then return end

    if HouseID == self:GetOwnHouseID() then
        self:SetOwnHouseID(0)
    elseif HouseID == self:GetSharedHouseID() then
        self:SetSharedHouseID(0)
    elseif HouseID == self:GetArmyHouseID() then
        self:SetArmyHouseID(0)
    elseif HouseID == self:GetArmyPersonalHouseID() then
        self:SetArmyPersonalHouseID(0)
    end

    local TargetAddr = MsgBody.DestoriedHouseBc.Addr or {}
    local GroupRooms, GroupHouses = {}, {}

    for __, Data in pairs(self.HouseDecorateDataManager) do
        local YardData = Data[ProtoRes.HouseRegionType.HouseRegionType_Yard]
        if YardData and YardData.Addr then
            -- 地址匹配检查
            local IsSameAddr = YardData.Addr.EstateID == TargetAddr.EstateID
                    and YardData.Addr.Area == TargetAddr.Area
                    and YardData.Addr.Number == TargetAddr.Number

            if IsSameAddr then
                if YardData.HouseType == ProtoCS.HouseType.HouseType_HouseType_GroupMemberRoom then
                    table.insert(GroupRooms, YardData.HouseID)
                else
                    table.insert(GroupHouses, YardData.HouseID)
                end
            end
        end
    end

    -- 清理组成员房间
    for _, RoomId in ipairs(GroupRooms) do
        self.HouseDecorateDataManager[RoomId] = nil
    end

    -- 清理房屋
    for _, GroupId in ipairs(GroupHouses) do
        self:DestroyHouseEntranceEObj(GroupId)
        self:HideHouse(GroupId)
    end
end

--食物变化后广播
function HousingMgr:FootEatBcNtf(MsgBody)
    local FootEatData = MsgBody and MsgBody.FootEatBc
    if not FootEatData then return end

    local HouseData = self.HouseDecorateDataManager[FootEatData.HouseID]
    if not HouseData then return end

    local RegionData = HouseData[FootEatData.Region]
    if not RegionData or not RegionData.Furniture then return end

    for _, Entity in ipairs(RegionData.Furniture.Entities) do
        if Entity.GID == FootEatData.FurnitureID then
            Entity.Attr.Food.EatedTimes = FootEatData.EatedTimes
            _G.EventMgr:SendEvent(EventID.FurnitureDataUpdate, MsgBody)
            return
        end
    end
end

function HousingMgr:ChangeStatusBcNtf(MsgBody)
    local StatusData = MsgBody and MsgBody.ChangeStatusBc
    if not StatusData then return end

    local HouseData = self.HouseDecorateDataManager[StatusData.HouseID]
    if not HouseData then return end

    local RegionData = HouseData[StatusData.Region]
    if not (RegionData and RegionData.Furniture and RegionData.Furniture.Entities) then return end

    for _, Entity in ipairs(RegionData.Furniture.Entities) do
        if Entity.GID == StatusData.FurnitureID then
            Entity.Attr = Entity.Attr or {}
            Entity.Attr.Status = Entity.Attr.Status or {}
            Entity.Attr.Status.CurStatus = StatusData.Status
            return
        end
    end
end

---房屋家具统计, 这是返回的是缓存的数据
---@param InHouseID number
---@param Region number
---@return number
function HousingMgr:GetOwnerHouseFurnitureCount(InHouseID, Region)
    local HouseData = self.HouseDecorateDataManager[InHouseID]
    if not HouseData then
        return 0
    end

    local TargetRegions = {}
    if Region then
        TargetRegions[#TargetRegions + 1] = Region
    else
        -- 默认统计房间和庭院
        TargetRegions = {
            ProtoRes.HouseRegionType.HouseRegionType_Room,
            ProtoRes.HouseRegionType.HouseRegionType_Yard
        }
    end

    local TotalCount = 0
    for _, RegionType in ipairs(TargetRegions) do
        local RegionData = HouseData[RegionType]
        if RegionData and RegionData.Furniture then
            TotalCount = TotalCount + (RegionData.Furniture.Entities and #RegionData.Furniture.Entities or 0)
        end
    end

    return TotalCount
end

---仓库库存统计, 这是返回的是缓存的数据
---@param Region number
---@return number
function HousingMgr:GetOwnerDepotItemCount(HouseID, Region)
    local TargetRegions = Region and { Region } or {
        ProtoRes.HouseRegionType.HouseRegionType_Room,
        ProtoRes.HouseRegionType.HouseRegionType_Yard
    }

    local TotalCount = 0
    for _, RegionType in ipairs(TargetRegions) do
        local Depot = self:GetDepotData(HouseID, RegionType)
        TotalCount = TotalCount + (Depot.ItemList and #Depot.ItemList or 0)
    end

    return TotalCount
end

